"""Independent FlyDSL MXFP4 routed MoE, with reference-compatible rounding.

Both projections use block-scaled FP4 MFMA and FP32 accumulation. Activations
are rounded to MXFP4 twice, with the intermediate first rounded to BF16.
Expert routing, layout staging, SiLU and the weighted reduction run on the GPU
in kernels defined here. Torch is used only to allocate and retain buffers.
"""

import torch
import os
import sys
import flydsl.compiler as flyc
import flydsl.expr as fx
from flydsl.expr import rocdl, gpu
from flydsl.expr.typing import T, ReductionOp
from flydsl.extension.coop.warp import warp_reduce, warp_inclusive_scan
from flydsl._mlir.dialects import llvm


def _sweep(name, default):
    value = int(default)
    return value


def _sweep_bool(name, default):
    value = _sweep(name, int(default))
    if value not in (0, 1):
        raise ValueError(f'{name} must be 0 or 1')
    return value == 1


_DPP_SCAN = _sweep_bool('DPP_SCAN', True)
_DPP_INPUT = _sweep_bool('DPP_INPUT', True)


def _ptr(addr, dtype, alignment=4):
    return fx.inttoptr(fx.PointerType.get(dtype.ir_type, fx.AddressSpace.Global, alignment), fx.Int64(addr))


def _load(addr, offset, dtype=fx.Int32):
    if dtype == fx.Uint8:
        rsrc = rocdl.get_buffer_rsrc(rocdl.make_buffer_ptr(_ptr(addr, fx.Uint8, 1)))
        return fx.Uint8(rocdl.raw_ptr_buffer_load(T.i8, rsrc, fx.Int32(offset), fx.Int32(0), 0))
    return fx.ptr_load(fx.add_offset(_ptr(addr, dtype, dtype.width // 8), offset))


def _store(addr, offset, value, dtype=fx.Int32):
    fx.ptr_store(dtype(value), fx.add_offset(_ptr(addr, dtype, dtype.width // 8), offset))


def _load4(addr, offset, CACHE=0):
    rsrc = rocdl.get_buffer_rsrc(rocdl.make_buffer_ptr(_ptr(addr, fx.Int32, 16)))
    return fx.Vector(rocdl.raw_ptr_buffer_load(T.i32x4, rsrc, fx.Int32(offset) * 4, fx.Int32(0), CACHE))


def _load4_lds(addr, offset, destination):
    rsrc = rocdl.get_buffer_rsrc(rocdl.make_buffer_ptr(_ptr(addr, fx.Int32, 16)))
    address = fx.Int32(fx.ptrtoint(destination))
    uniform = fx.Int32(rocdl.readfirstlane(T.i32, address))
    pointer = fx.inttoptr(fx.PointerType.get(fx.Int32.ir_type, fx.AddressSpace.Shared, 16), uniform)
    rocdl.raw_ptr_buffer_load_lds(rsrc, fx.to_llvm_ptr(pointer), fx.Int32(16),
                               fx.Int32(offset) * 4, fx.Int32(0), fx.Int32(0), 0)


def _max(a, b):
    return (a > b).select(a, b)


def _input_max(a, b):
    if fx.const_expr(_DPP_INPUT):
        result = fx.Float32(fx.maxnumf(a, b))
    else:
        result = _max(a, b)
    return result


def _amax_reduce(a, steps, INPUT=False):
    # Nonnegative finite float bit patterns have the same unsigned ordering.
    # The gfx950 subgroup collective folds DPP moves into native max ops.
    if fx.const_expr(INPUT and _DPP_INPUT):
        a = warp_reduce(a.bitcast(fx.Uint32), ReductionOp.MAX,
                        width=1 << steps).bitcast(fx.Float32)
    else:
        for step in range(steps):
            a = _max(a, fx.Float32(gpu.shuffle_xor(a, 1 << step, 64)))
    return a


def _epilogue_reduce(a, DPP):
    if fx.const_expr(DPP):
        # Finite nonnegative magnitudes are ordered by their unsigned bits.
        # DPP combines the cross-lane move and max in each reduction step.
        a = warp_reduce(a.bitcast(fx.Uint32), ReductionOp.MAX,
                        width=16).bitcast(fx.Float32)
    else:
        for step in range(4):
            a = _max(a, fx.Float32(gpu.shuffle_xor(a, 1 << step, 64)))
    return a


def _prefix64(value, lane):
    if fx.const_expr(_DPP_SCAN):
        value = warp_inclusive_scan(value, ReductionOp.ADD, width=64)
    else:
        for step in range(6):
            left = fx.Int32(gpu.shuffle_up(value, 1 << step, 64))
            value = value + (lane >= (1 << step)).select(left, fx.Int32(0))
    return value


def _scale_offset(e, n, kg, N, K, ADDR_BITS):
    # [E,N/32,K/256,4,16,2,2], inverse of the stored scale permutation.
    # Power-of-two coordinates map directly to the packed address bits.
    if fx.const_expr(ADDR_BITS):
        offset = (e * N * (K // 32) + (n >> 5) * (K // 256) * 256
                  + (kg >> 3) * 256 + (kg & 3) * 64
                  + (n & 15) * 4 + ((kg >> 2) & 1) * 2 + ((n >> 4) & 1))
    else:
        offset = (e * N * (K // 32) + (n // 32) * (K // 256) * 256
                  + (kg // 8) * 256 + (kg % 4) * 64
                  + (n % 16) * 4 + (kg % 8 // 4) * 2 + (n % 32 // 16))
    return offset


def _weight_offset(e, n, kg, N, K, ADDR_BITS):
    # 32 FP4 values (16 bytes) of one logical weight row per lane.
    # The two interleaved K halves advance by a single 64-dword stride.
    if fx.const_expr(ADDR_BITS):
        offset = (e * N * (K // 8) + (n >> 4) * (K // 8) * 16
                  + kg * 64 + (n & 15) * 4)
    else:
        offset = (e * N * (K // 8) + (n // 16) * (K // 8) * 16
                  + (kg // 2) * 128 + (kg % 2) * 64 + (n % 16) * 4)
    return offset


def _mfma(a, b, c, sa, sb):
    return fx.Vector(rocdl.mfma_scale_f32_16x16x128_f8f6f4(
        T.f32x4, [a, b, c, 4, 4, 0, sa, 0, sb]))


def _mfma2(a, b, c, sa, sb, WIDE):
    if fx.const_expr(WIDE):
        return fx.Vector(rocdl.mfma_scale_f32_32x32x64_f8f6f4(
            fx.Vector.make_type(16, fx.Float32), [a, b, c, 4, 4, 0, sa, 0, sb]))
    else:
        return _mfma(a, b, c, sa, sb)


def _silu_bf16(g, u):
    exp_neg = fx.Float32(rocdl.exp2(T.f32, (-g * fx.Float32(1.4426950408889634)).ir_value()))
    inv = fx.Float32(rocdl.rcp(T.f32, (fx.Float32(1.0) + exp_neg).ir_value()))
    return fx.Float32(fx.BFloat16((g * inv) * u))


def _chiplet_order(pid, bound):
    chiplet = pid % 8
    quotient, remainder = bound // 8, bound % 8
    return chiplet * quotient + (chiplet < remainder).select(chiplet, remainder) + pid // 8


def _routed_row(Routes, offset, tile, DIRECT):
    rid = tile
    if fx.const_expr(not DIRECT):
        rid = _load(Routes, offset)
    return rid


def _w1_operands(W, WS, e, nbase, wave, lane, kg, I, D, BN, WAVES, ADDR_BITS, CACHE, PACKED):
    result = []
    for ni in range(BN // (WAVES * 16)):
        n = nbase + wave * (BN // WAVES) + ni * 16 + lane % 16
        result.extend([_load4(W, _weight_offset(e, n, kg, 2 * I, D, ADDR_BITS), CACHE),
                       _load4(W, _weight_offset(e, n + I, kg, 2 * I, D, ADDR_BITS), CACHE),
                       _w2_scale(WS, e, n, kg, 2 * I, D, ADDR_BITS, PACKED),
                       _w2_scale(WS, e, n + I, kg, 2 * I, D, ADDR_BITS, PACKED)])
    return result


def _w2_scale(WS, e, n, kg, D, I, ADDR_BITS, PACKED):
    if fx.const_expr(PACKED):
        # Each word contains two 16-column halves and two adjacent K slices.
        # Aligned words can be reused by the unrolled column and K loops.
        offset = (e * D * (I // 128) + (n >> 5) * (I // 256) * 64
                  + (kg >> 3) * 64 + (kg & 3) * 16 + (n & 15))
        word = _load(WS, offset)
        shift = ((((kg >> 2) & 1) * 2 + ((n >> 4) & 1)) * 8)
        scale = (word >> shift) & 255
    else:
        scale = fx.Int32(_load(WS, _scale_offset(e, n, kg, D, I, ADDR_BITS), fx.Uint8))
    return scale


def _w2_operands(W, WS, e, nbase, wave, lane, kg, D, I, BN, FRAG, ADDR_BITS, CACHE, PACKED):
    result = []
    for ni in range(BN // (FRAG * 4)):
        n = nbase + wave * (BN // 4) + ni * FRAG + lane % FRAG
        result.extend([_load4(W, _weight_offset(e, n, kg, D, I, ADDR_BITS), CACHE),
                       _w2_scale(WS, e, n, kg, D, I, ADDR_BITS, PACKED)])
    return result


@flyc.kernel
def _quantize(X: fx.Int64, Q: fx.Int64, S: fx.Int64, Counts: fx.Int64,
              TOTAL: fx.Constexpr[int], E: fx.Constexpr[int], CLEAR: fx.Constexpr[bool]):
    t = fx.Int32(fx.block_idx.x) * 256 + fx.Int32(fx.thread_idx.x)
    if fx.const_expr(CLEAR):
        if t < E:
            _store(Counts, t, 0)
    if t < TOTAL // 2:
        x0 = fx.Float32(_load(X, t * 2, fx.BFloat16))
        x1 = fx.Float32(_load(X, t * 2 + 1, fx.BFloat16))
        a = _input_max(fx.absf(x0), fx.absf(x1))
        a = _amax_reduce(a, 4, True)
        a = _input_max(a, fx.Float32(1.0e-10))
        # Exact frexp(a).exponent - 3 + (mantissa > .75), no division.
        bits = a.bitcast(fx.Int32)
        exponent = ((bits >> 23) & 255) - 2 + ((bits & 0x7fffff) > 0x400000).select(fx.Int32(1), fx.Int32(0))
        scale = (exponent << 23).bitcast(fx.Float32)
        packed = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, x1, scale, 0))
        _store(Q, t, packed, fx.Uint8)
        if t % 16 == 0:
            _store(S, t // 16, exponent, fx.Uint8)


@flyc.kernel
def _route(Ids: fx.Int64, Counts: fx.Int64, Routes: fx.Int64, R: fx.Constexpr[int]):
    tid = fx.Int32(fx.thread_idx.x)
    lane = tid % 64
    r = fx.Int32(fx.block_idx.x) * 256 + tid
    e = fx.Int32(fx.block_idx.y)
    match = fx.Boolean(False)
    if r < R:
        match = _load(Ids, r) == e
    mask = fx.Uint64(rocdl.ballot(T.i64, match))
    count = fx.Int32(fx.ctpop(mask))
    rank = fx.Int32(fx.ctpop(mask & ((fx.Uint64(1) << fx.Uint64(lane)) - fx.Uint64(1))))
    base = fx.Int32(0)
    if lane == 0:
        p = fx.to_llvm_ptr(fx.add_offset(_ptr(Counts, fx.Int32), e))
        base = fx.Int32(llvm.atomicrmw(llvm.AtomicBinOp.add, p, count.ir_value(), llvm.AtomicOrdering.monotonic))
    base = fx.Int32(gpu.shuffle_idx(base, 0, 64))
    if match:
        _store(Routes, e * R + base + rank, r)


@flyc.kernel
def _route_block(Ids: fx.Int64, Counts: fx.Int64, Routes: fx.Int64, R: fx.Constexpr[int]):
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    r = fx.Int32(fx.block_idx.x) * 256 + tid
    e = fx.Int32(fx.block_idx.y)
    offsets = fx.recast_iter(fx.Int32, fx.SharedAllocator().allocate(16, alignment=16).peek().ptr)
    match = fx.Boolean(False)
    if r < R:
        match = _load(Ids, r) == e
    mask = fx.Uint64(rocdl.ballot(T.i64, match))
    count = fx.Int32(fx.ctpop(mask))
    rank = fx.Int32(fx.ctpop(mask & ((fx.Uint64(1) << fx.Uint64(lane)) - fx.Uint64(1))))
    if lane == 0:
        fx.ptr_store(count, fx.add_offset(offsets, wave))
    gpu.barrier()
    if tid == 0:
        c0 = fx.Int32(fx.ptr_load(offsets))
        c1 = fx.Int32(fx.ptr_load(fx.add_offset(offsets, 1)))
        c2 = fx.Int32(fx.ptr_load(fx.add_offset(offsets, 2)))
        c3 = fx.Int32(fx.ptr_load(fx.add_offset(offsets, 3)))
        total = c0 + c1 + c2 + c3
        base = fx.Int32(0)
        if total > 0:
            p = fx.to_llvm_ptr(fx.add_offset(_ptr(Counts, fx.Int32), e))
            base = fx.Int32(llvm.atomicrmw(llvm.AtomicBinOp.add, p, total.ir_value(), llvm.AtomicOrdering.monotonic))
        fx.ptr_store(base, offsets)
        fx.ptr_store(base + c0, fx.add_offset(offsets, 1))
        fx.ptr_store(base + c0 + c1, fx.add_offset(offsets, 2))
        fx.ptr_store(base + c0 + c1 + c2, fx.add_offset(offsets, 3))
    gpu.barrier()
    base = fx.Int32(fx.ptr_load(fx.add_offset(offsets, wave)))
    if match:
        _store(Routes, e * R + base + rank, r)


def _quantize_eight(X, t):
    # Four adjacent lanes own one complete 32-value MXFP4 scale group.
    packed_input = _load4(X, t * 4).bitcast(fx.BFloat16)
    values = [fx.Float32(packed_input[j]) for j in range(8)]
    a = fx.absf(values[0])
    for j in range(1, 8):
        a = _input_max(a, fx.absf(values[j]))
    a = _amax_reduce(a, 2, True)
    a = _input_max(a, fx.Float32(1.0e-10))
    bits = a.bitcast(fx.Int32)
    exponent = ((bits >> 23) & 255) - 2 + ((bits & 0x7fffff) > 0x400000).select(fx.Int32(1), fx.Int32(0))
    scale = (exponent << 23).bitcast(fx.Float32)
    packed = fx.Int32(0)
    for j in range(4):
        packed = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, packed, values[j * 2], values[j * 2 + 1], scale, j))
    return packed, exponent


@flyc.kernel
def _route_expert(Ids: fx.Int64, Counts: fx.Int64, Routes: fx.Int64,
                  R: fx.Constexpr[int], WAVES: fx.Constexpr[int],
                  X: fx.Int64, Q: fx.Int64, S: fx.Int64,
                  SIZE: fx.Constexpr[int], E: fx.Constexpr[int], QUANT: fx.Constexpr[bool], VEC: fx.Constexpr[bool], TWO_PASS: fx.Constexpr[bool]):
    # Each workgroup owns an expert and compacts its routes in input order.
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    e = fx.Int32(fx.block_idx.x)
    shared = fx.recast_iter(fx.Int32, fx.SharedAllocator().allocate(WAVES * 8, alignment=16).peek().ptr)
    if fx.const_expr(QUANT):
        # Quantization fills the grid; the first E workgroups also own the
        # independent expert scans. Their work overlaps on the remaining CUs.
        t = e * (WAVES * 64) + tid
        if fx.const_expr(VEC):
            if t < SIZE // 8:
                packed, exponent = _quantize_eight(X, t)
                _store(Q, t, packed)
                if t % 4 == 0:
                    _store(S, t // 4, exponent, fx.Uint8)
        elif t < SIZE // 2:
            x0 = fx.Float32(_load(X, t * 2, fx.BFloat16))
            x1 = fx.Float32(_load(X, t * 2 + 1, fx.BFloat16))
            a = _input_max(fx.absf(x0), fx.absf(x1))
            a = _amax_reduce(a, 4, True)
            a = _input_max(a, fx.Float32(1.0e-10))
            bits = a.bitcast(fx.Int32)
            exponent = ((bits >> 23) & 255) - 2 + ((bits & 0x7fffff) > 0x400000).select(fx.Int32(1), fx.Int32(0))
            scale = (exponent << 23).bitcast(fx.Float32)
            packed = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, x1, scale, 0))
            _store(Q, t, packed, fx.Uint8)
            if t % 16 == 0:
                _store(S, t // 16, exponent, fx.Uint8)
    if fx.const_expr(not QUANT) or e < E:
        if fx.const_expr(TWO_PASS):
            # Each wave counts a contiguous input segment, then writes it
            # using one shared prefix scan instead of a scan per chunk.
            CHUNKS = (R + WAVES * 64 - 1) // (WAVES * 64)
            for chunk, state in range(0, CHUNKS, 1, init=[fx.Int32(0)]):
                r = (wave * CHUNKS + fx.Int32(chunk)) * 64 + lane
                match = fx.Boolean(False)
                if r < R:
                    match = _load(Ids, r) == e
                mask = fx.Uint64(rocdl.ballot(T.i64, match))
                result = yield [fx.Int32(state[0]) + fx.Int32(fx.ctpop(mask))]
            if lane == 0:
                fx.ptr_store(result, fx.add_offset(shared, wave))
            gpu.barrier()
            if wave == 0:
                prefix = fx.Int32(0)
                if lane < WAVES:
                    prefix = fx.Int32(fx.ptr_load(fx.add_offset(shared, lane)))
                prefix = _prefix64(prefix, lane)
                if lane < WAVES:
                    fx.ptr_store(prefix, fx.add_offset(shared, lane))
            gpu.barrier()
            if tid == 0:
                _store(Counts, e, fx.Int32(fx.ptr_load(fx.add_offset(shared, WAVES - 1))))
            base = fx.Int32(0)
            if wave > 0:
                base = fx.Int32(fx.ptr_load(fx.add_offset(shared, wave - 1)))
            for chunk, state in range(0, CHUNKS, 1, init=[base]):
                r = (wave * CHUNKS + fx.Int32(chunk)) * 64 + lane
                match = fx.Boolean(False)
                if r < R:
                    match = _load(Ids, r) == e
                mask = fx.Uint64(rocdl.ballot(T.i64, match))
                rank = fx.Int32(fx.ctpop(mask & ((fx.Uint64(1) << fx.Uint64(lane)) - fx.Uint64(1))))
                if match:
                    _store(Routes, e * R + fx.Int32(state[0]) + rank, r)
                result = yield [fx.Int32(state[0]) + fx.Int32(fx.ctpop(mask))]
        else:
            for chunk, state in range(0, (R + WAVES * 64 - 1) // (WAVES * 64), 1, init=[fx.Int32(0)]):
                total = fx.Int32(state[0])
                r = fx.Int32(chunk) * (WAVES * 64) + tid
                match = fx.Boolean(False)
                if r < R:
                    match = _load(Ids, r) == e
                mask = fx.Uint64(rocdl.ballot(T.i64, match))
                count = fx.Int32(fx.ctpop(mask))
                rank = fx.Int32(fx.ctpop(mask & ((fx.Uint64(1) << fx.Uint64(lane)) - fx.Uint64(1))))
                # Alternate scan buffers while other waves consume earlier offsets.
                buf = (fx.Int32(chunk) & 1) * WAVES
                if lane == 0:
                    fx.ptr_store(count, fx.add_offset(shared, buf + wave))
                gpu.barrier()
                if wave == 0:
                    prefix = fx.Int32(0)
                    if lane < WAVES:
                        prefix = fx.Int32(fx.ptr_load(fx.add_offset(shared, buf + lane)))
                    prefix = _prefix64(prefix, lane)
                    if lane < WAVES:
                        fx.ptr_store(prefix, fx.add_offset(shared, buf + lane))
                gpu.barrier()
                offset = fx.Int32(0)
                if wave > 0:
                    offset = fx.Int32(fx.ptr_load(fx.add_offset(shared, buf + wave - 1)))
                if match:
                    _store(Routes, e * R + total + offset + rank, r)
                increment = fx.Int32(fx.ptr_load(fx.add_offset(shared, buf + WAVES - 1)))
                result = yield [total + increment]
            if tid == 0:
                _store(Counts, e, result)


@flyc.kernel
def _route_fused(Ids: fx.Int64, Counts: fx.Int64, Routes: fx.Int64,
                 TileE: fx.Int64, TileR: fx.Int64, Total: fx.Int64,
                 R: fx.Constexpr[int], E: fx.Constexpr[int], BM: fx.Constexpr[int],
                 WAVES: fx.Constexpr[int]):
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    shared = fx.recast_iter(fx.Int32, fx.SharedAllocator().allocate(E * 4, alignment=16).peek().ptr)
    # Each wave owns an expert at a time, so its routes and count need no atomics.
    for group in fx.range_constexpr((E + WAVES - 1) // WAVES):
        e = group * WAVES + wave
        count = fx.Int32(0)
        for chunk in fx.range_constexpr((R + 63) // 64):
            r = chunk * 64 + lane
            match = fx.Boolean(False)
            if e < E and r < R:
                match = _load(Ids, r) == e
            mask = fx.Uint64(rocdl.ballot(T.i64, match))
            rank = fx.Int32(fx.ctpop(mask & ((fx.Uint64(1) << fx.Uint64(lane)) - fx.Uint64(1))))
            if match:
                _store(Routes, e * R + count + rank, r)
            count = count + fx.Int32(fx.ctpop(mask))
        if e < E and lane == 0:
            _store(Counts, e, count)
            fx.ptr_store(count, fx.add_offset(shared, e))
    gpu.barrier()
    # The first wave compacts all expert tile counts after routing completes.
    if tid < 64:
        cnt = fx.Int32(0)
        if tid < E:
            cnt = (fx.Int32(fx.ptr_load(fx.add_offset(shared, tid))) + BM - 1) // BM
        prefix = cnt
        prefix = _prefix64(prefix, tid)
        if tid == 63:
            _store(Total, 0, prefix)
        for j in range(cnt):
            _store(TileE, prefix - cnt + fx.Int32(j), tid)
            _store(TileR, prefix - cnt + fx.Int32(j), fx.Int32(j) * BM)


@flyc.kernel
def _quantize_route_fused(X: fx.Int64, Q: fx.Int64, S: fx.Int64,
                          Ids: fx.Int64, Counts: fx.Int64, Routes: fx.Int64,
                          TileE: fx.Int64, TileR: fx.Int64, Total: fx.Int64,
                          SIZE: fx.Constexpr[int], R: fx.Constexpr[int],
                          E: fx.Constexpr[int], BM: fx.Constexpr[int],
                          WAVES: fx.Constexpr[int]):
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    t = fx.Int32(fx.block_idx.x) * (WAVES * 64) + tid
    shared = fx.recast_iter(fx.Int32, fx.SharedAllocator().allocate(E * 4, alignment=16).peek().ptr)
    if t < SIZE // 2:
        x0 = fx.Float32(_load(X, t * 2, fx.BFloat16))
        x1 = fx.Float32(_load(X, t * 2 + 1, fx.BFloat16))
        a = _input_max(fx.absf(x0), fx.absf(x1))
        a = _amax_reduce(a, 4, True)
        a = _input_max(a, fx.Float32(1.0e-10))
        bits = a.bitcast(fx.Int32)
        exponent = ((bits >> 23) & 255) - 2 + ((bits & 0x7fffff) > 0x400000).select(fx.Int32(1), fx.Int32(0))
        scale = (exponent << 23).bitcast(fx.Float32)
        packed = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, x1, scale, 0))
        _store(Q, t, packed, fx.Uint8)
        if t % 16 == 0:
            _store(S, t // 16, exponent, fx.Uint8)
    # Routing is independent of quantization. One CTA owns its complete state;
    # the following projection launch waits for both preparation tasks.
    if fx.Int32(fx.block_idx.x) == 0:
        for group in fx.range_constexpr((E + WAVES - 1) // WAVES):
            e = group * WAVES + wave
            count = fx.Int32(0)
            for chunk in fx.range_constexpr((R + 63) // 64):
                r = chunk * 64 + lane
                match = fx.Boolean(False)
                if e < E and r < R:
                    match = _load(Ids, r) == e
                mask = fx.Uint64(rocdl.ballot(T.i64, match))
                rank = fx.Int32(fx.ctpop(mask & ((fx.Uint64(1) << fx.Uint64(lane)) - fx.Uint64(1))))
                if match:
                    _store(Routes, e * R + count + rank, r)
                count = count + fx.Int32(fx.ctpop(mask))
            if e < E and lane == 0:
                _store(Counts, e, count)
                fx.ptr_store(count, fx.add_offset(shared, e))
        gpu.barrier()
        if tid < 64:
            cnt = fx.Int32(0)
            if tid < E:
                cnt = (fx.Int32(fx.ptr_load(fx.add_offset(shared, tid))) + BM - 1) // BM
            prefix = cnt
            prefix = _prefix64(prefix, tid)
            if tid == 63:
                _store(Total, 0, prefix)
            for j in range(cnt):
                _store(TileE, prefix - cnt + fx.Int32(j), tid)
                _store(TileR, prefix - cnt + fx.Int32(j), fx.Int32(j) * BM)


@flyc.kernel
def _route_tiles(Counts: fx.Int64, TileE: fx.Int64, TileR: fx.Int64, Total: fx.Int64,
                 E: fx.Constexpr[int], BM: fx.Constexpr[int]):
    e = fx.Int32(fx.thread_idx.x)
    cnt = fx.Int32(0)
    if e < E:
        cnt = (_load(Counts, e) + BM - 1) // BM
    prefix = cnt
    prefix = _prefix64(prefix, e)
    if e == 63:
        _store(Total, 0, prefix)
    for j in range(cnt):
        _store(TileE, prefix - cnt + fx.Int32(j), e)
        _store(TileR, prefix - cnt + fx.Int32(j), fx.Int32(j) * BM)


def _map_expert_tile(Counts, tile, lane, E, BM):
    # All waves derive the same tile mapping from the completed expert counts.
    index = (lane < E).select(lane, fx.Int32(0))
    count = _load(Counts, index)
    tiles = (lane < E).select((count + BM - 1) // BM, fx.Int32(0))
    prefix = tiles
    prefix = _prefix64(prefix, lane)
    total = fx.Int32(gpu.shuffle_idx(prefix, 63, 64))
    mask = fx.Uint64(rocdl.ballot(T.i64, prefix > tile))
    expert = fx.Int32(64) - fx.Int32(fx.ctpop(mask))
    expert = (tile < total).select(expert, fx.Int32(0))
    end = fx.Int32(gpu.shuffle_idx(prefix, expert, 64))
    length = fx.Int32(gpu.shuffle_idx(tiles, expert, 64))
    return total, expert, (tile - end + length) * BM


@flyc.kernel
def _gather_quant(A: fx.Int64, AS: fx.Int64, B: fx.Int64, BS: fx.Int64,
                  Routes: fx.Int64, Counts: fx.Int64, TE: fx.Int64, TR: fx.Int64,
                  Total: fx.Int64, R: fx.Constexpr[int], K: fx.Constexpr[int],
                  TOPK: fx.Constexpr[int], BM: fx.Constexpr[int], ROW_PAD: fx.Constexpr[int], E: fx.Constexpr[int], MAP_TILES: fx.Constexpr[bool]):
    tile = fx.Int32(fx.block_idx.y)
    t = fx.Int32(fx.block_idx.x) * 256 + fx.Int32(fx.thread_idx.x)
    if fx.const_expr(MAP_TILES):
        total, expert, first_row = _map_expert_tile(Counts, tile, fx.Int32(fx.thread_idx.x) % 64, E, BM)
        if t == 0:
            if tile == 0:
                _store(Total, 0, total)
            if tile < total:
                _store(TE, tile, expert)
                _store(TR, tile, first_row)
    else:
        total = _load(Total, 0)
    if tile < total:
        if t < BM * (K // 32):
            row, kg = t % BM, t // BM
            if fx.const_expr(MAP_TILES):
                e, rr = expert, first_row + row
            else:
                e = _load(TE, tile)
                rr = _load(TR, tile) + row
            rid = fx.Int32(0)
            if rr < _load(Counts, e):
                rid = _load(Routes, e * R + rr)
            src = rid // TOPK
            v = _load4(A, src * (K // 8) + kg * 4)
            dst = (tile * (K // 32) + kg) * (BM + ROW_PAD) + row
            fx.ptr_store(v, fx.add_offset(_ptr(B, fx.Int32, 16), dst * 4))
            scale = _load(AS, src * (K // 32) + kg, fx.Uint8)
            _store(BS, dst, scale, fx.Uint8)


@flyc.kernel
def _gather_quant_coalesced(A: fx.Int64, AS: fx.Int64, B: fx.Int64, BS: fx.Int64,
                            Routes: fx.Int64, Counts: fx.Int64, TE: fx.Int64, TR: fx.Int64,
                            Total: fx.Int64, R: fx.Constexpr[int], K: fx.Constexpr[int],
                            TOPK: fx.Constexpr[int], BM: fx.Constexpr[int], ROW_PAD: fx.Constexpr[int], E: fx.Constexpr[int], MAP_TILES: fx.Constexpr[bool]):
    # Read 128 contiguous bytes per routed row, then transpose 32 rows by
    # eight packed scale groups into the projection's group-major layout.
    tile = fx.Int32(fx.block_idx.y)
    block = fx.Int32(fx.block_idx.x)
    tid = fx.Int32(fx.thread_idx.x)
    rbase = (block % (BM // 32)) * 32
    kbase = (block // (BM // 32)) * 8
    smem = fx.SharedAllocator()
    values = fx.recast_iter(fx.Int32, smem.allocate(256 * 16, alignment=16).peek().ptr)
    scales = fx.recast_iter(fx.Uint8, smem.allocate(256, alignment=16).peek().ptr)
    if fx.const_expr(MAP_TILES):
        total, expert, first_row = _map_expert_tile(Counts, tile, tid % 64, E, BM)
        if block == 0 and tid == 0:
            if tile == 0:
                _store(Total, 0, total)
            if tile < total:
                _store(TE, tile, expert)
                _store(TR, tile, first_row)
    else:
        total = _load(Total, 0)
    if tile < total:
        row, kg = tid // 8, tid % 8
        if fx.const_expr(MAP_TILES):
            e, rr = expert, first_row + rbase + row
        else:
            e = _load(TE, tile)
            rr = _load(TR, tile) + rbase + row
        rid = fx.Int32(0)
        if rr < _load(Counts, e):
            rid = _load(Routes, e * R + rr)
        src = rid // TOPK
        v = _load4(A, src * (K // 8) + (kbase + kg) * 4)
        scale = _load(AS, src * (K // 32) + kbase + kg, fx.Uint8)
        # The row-dependent XOR spreads transposed 16-byte reads over all
        # 64 LDS banks while retaining contiguous source-row accesses.
        index = row * 8 + (kg ^ ((row // 2) % 8))
        fx.ptr_store(v, fx.add_offset(values, index * 4))
        fx.ptr_store(scale, fx.add_offset(scales, index))
        gpu.barrier()
        row, kg = tid % 32, tid // 32
        index = row * 8 + (kg ^ ((row // 2) % 8))
        v = fx.ptr_load(fx.add_offset(values, index * 4), result_type=T.i32x4)
        scale = fx.Uint8(fx.ptr_load(fx.add_offset(scales, index)))
        dst = (tile * (K // 32) + kbase + kg) * (BM + ROW_PAD) + rbase + row
        fx.ptr_store(v, fx.add_offset(_ptr(B, fx.Int32, 16), dst * 4))
        _store(BS, dst, scale, fx.Uint8)


@flyc.kernel
def _gemm1(A: fx.Int64, AS: fx.Int64, W: fx.Int64, WS: fx.Int64,
           Routes: fx.Int64, Counts: fx.Int64, TileE: fx.Int64, TileR: fx.Int64,
           Total: fx.Int64, H: fx.Int64, Q: fx.Int64, QS: fx.Int64,
           R: fx.Constexpr[int], D: fx.Constexpr[int], I: fx.Constexpr[int],
           TOPK: fx.Constexpr[int], BM: fx.Constexpr[int], BN: fx.Constexpr[int],
           SORTED: fx.Constexpr[bool], PARTS: fx.Constexpr[int], LDS: fx.Constexpr[bool], PF: fx.Constexpr[bool], FUSED_Q: fx.Constexpr[bool], QMAX: fx.Constexpr[bool], DIRECT: fx.Constexpr[bool], KSTEP: fx.Constexpr[int], WAVES: fx.Constexpr[int], ADDR_BITS: fx.Constexpr[bool], GROUP_M: fx.Constexpr[int], PINGPONG: fx.Constexpr[bool], DMA: fx.Constexpr[bool], ROW_PAD: fx.Constexpr[int], CACHE: fx.Constexpr[int], PACKED: fx.Constexpr[bool], ROW_MAJOR: fx.Constexpr[bool], QSHUFFLE: fx.Constexpr[bool], EPILOGUE_DPP: fx.Constexpr[bool]):
    THREADS = WAVES * 64
    NR = BN // (WAVES * 16)
    pid = fx.Int32(fx.block_idx.x)
    bound = fx.Int32(R * (I // BN))
    if fx.const_expr(not DIRECT):
        bound = _load(Total, 0) * (I // BN)
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    split = fx.Int32(fx.block_idx.y)
    smem = fx.SharedAllocator()
    if fx.const_expr(LDS):
        shared = fx.recast_iter(fx.Int32, smem.allocate(BM * 4 * 20 * KSTEP * (2 if PINGPONG else 1), alignment=16).peek().ptr)
    if fx.const_expr(FUSED_Q and BN // WAVES == 16):
        qshared = fx.recast_iter(fx.Float32, smem.allocate(BM * (WAVES if QMAX else BN + 4) * 4, alignment=16).peek().ptr)
    if fx.const_expr(QSHUFFLE):
        qbytes = fx.recast_iter(fx.Uint8, smem.allocate(BM * BN // 2, alignment=16).peek().ptr)
        qwords = fx.recast_iter(fx.Int32, qbytes)
    if pid < bound:
        ordered = _chiplet_order(pid, bound)
        tile = ordered // (I // BN)
        nbase = ordered % (I // BN) * BN
        e = _load(TileE, tile)
        rb, count = fx.Int32(0), fx.Int32(1)
        if fx.const_expr(not DIRECT):
            rb = _load(TileR, tile)
            count = _load(Counts, e)
        if fx.const_expr(GROUP_M > 1):
            # Transpose complete row-tile groups within one expert. An
            # incomplete final group keeps its original traversal.
            member = (rb // BM) % GROUP_M
            first_row = rb - member * BM
            if first_row + (GROUP_M - 1) * BM < count:
                local = member * (I // BN) + ordered % (I // BN)
                tile = tile - member + local % GROUP_M
                rb = first_row + (local % GROUP_M) * BM
                nbase = (local // GROUP_M) * BN
        rows = []
        for mi in fx.range_constexpr(BM // 16):
            row = rb + mi * 16 + lane % 16
            rid = fx.Int32(0)
            if row < count:
                rid = _routed_row(Routes, e * R + row, tile, DIRECT)
            rows.append(rid // TOPK)
        zeros = [fx.Vector.filled(4, 0.0, fx.Float32) for _ in range(BM // 16 * NR * 2)]
        if fx.const_expr(PF):
            zeros = zeros + _w1_operands(W, WS, e, nbase, wave, lane, split * (D // 32 // PARTS) + lane // 16, I, D, BN, WAVES, ADDR_BITS, CACHE, PACKED)
        for kk, state in range(0, D // 128 // PARTS, KSTEP, init=zeros):
            lds_base = fx.Int32(0)
            if fx.const_expr(SORTED and LDS):
                if fx.const_expr(PINGPONG):
                    lds_base = ((fx.Int32(kk) // KSTEP) & 1) * (BM * 20 * KSTEP)
                else:
                    gpu.barrier()
                for cp in fx.range_constexpr((BM * 4 * KSTEP + THREADS - 1) // THREADS):
                    ix = tid + cp * THREADS
                    if ix < BM * 4 * KSTEP:
                        gi = (tile * (D // 32) + fx.Int32(kk) * 4) * BM + ix
                        if fx.const_expr(ROW_PAD != 0):
                            gi = (tile * (D // 32) + fx.Int32(kk) * 4 + ix // BM) * (BM + ROW_PAD) + ix % BM
                        if fx.const_expr(DMA):
                            _load4_lds(A, gi * 4, fx.add_offset(shared, lds_base + (wave * 64 + cp * THREADS) * 4))
                            ss = fx.Int32(_load(AS, gi, fx.Uint8))
                            fx.ptr_store(ss, fx.add_offset(shared, lds_base + BM * 16 * KSTEP + ix))
                        else:
                            vv = _load4(A, gi * 4)
                            ss = fx.Int32(_load(AS, gi, fx.Uint8))
                            fx.ptr_store(vv, fx.add_offset(shared, lds_base + ix * 4))
                            fx.ptr_store(ss, fx.add_offset(shared, lds_base + BM * 16 * KSTEP + ix))
                if fx.const_expr(DMA):
                    rocdl.s_waitcnt(vmcnt=0)
                gpu.barrier()
            accum = [fx.Vector(x) for x in state[:BM // 16 * NR * 2]]
            if fx.const_expr(PF):
                current_w = state[BM // 16 * NR * 2:]
            for ki in fx.range_constexpr(KSTEP):
                kg = ((fx.Int32(kk) + ki) + split * (D // 128 // PARTS)) * 4 + lane // 16
                if fx.const_expr(ROW_MAJOR):
                    operands = _w1_operands(W, WS, e, nbase, wave, lane, kg, I, D, BN, WAVES, ADDR_BITS, CACHE, PACKED)
                    for mi in fx.range_constexpr(BM // 16):
                        ix = (ki * 4 + lane // 16) * BM + mi * 16 + lane % 16
                        av = fx.ptr_load(fx.add_offset(shared, lds_base + ix * 4), result_type=T.i32x4)
                        asc = fx.Int32(fx.ptr_load(fx.add_offset(shared, lds_base + BM * 16 * KSTEP + ix)))
                        for ni in fx.range_constexpr(NR):
                            ai = (mi * NR + ni) * 2
                            accum[ai] = _mfma(av, fx.Vector(operands[ni * 4]), accum[ai], asc, fx.Int32(operands[ni * 4 + 2]))
                            accum[ai + 1] = _mfma(av, fx.Vector(operands[ni * 4 + 1]), accum[ai + 1], asc, fx.Int32(operands[ni * 4 + 3]))
                else:
                    if fx.const_expr(SORTED):
                        if fx.const_expr(LDS):
                            indices = [(ki * 4 + lane // 16) * BM + mi * 16 + lane % 16 for mi in range(BM // 16)]
                            av = [fx.ptr_load(fx.add_offset(shared, lds_base + indices[mi] * 4), result_type=T.i32x4) for mi in range(BM // 16)]
                            asc = [fx.Int32(fx.ptr_load(fx.add_offset(shared, lds_base + BM * 16 * KSTEP + indices[mi]))) for mi in range(BM // 16)]
                        else:
                            indices = [(tile * (D // 32) + kg) * (BM + ROW_PAD) + mi * 16 + lane % 16 for mi in range(BM // 16)]
                            av = [_load4(A, indices[mi] * 4) for mi in range(BM // 16)]
                            asc = [fx.Int32(_load(AS, indices[mi], fx.Uint8)) for mi in range(BM // 16)]
                    else:
                        av = [_load4(A, rows[mi] * (D // 8) + kg * 4) for mi in range(BM // 16)]
                        asc = [fx.Int32(_load(AS, rows[mi] * (D // 32) + kg, fx.Uint8)) for mi in range(BM // 16)]
                    if fx.const_expr(PF):
                        nextkk = ((fx.Int32(kk) + ki) + 1 < D // 128 // PARTS).select((fx.Int32(kk) + ki) + 1, (fx.Int32(kk) + ki))
                        next_w = _w1_operands(W, WS, e, nbase, wave, lane, (nextkk + split * (D // 128 // PARTS)) * 4 + lane // 16, I, D, BN, WAVES, ADDR_BITS, CACHE, PACKED)
                    for ni in fx.range_constexpr(NR):
                        n = nbase + wave * (BN // WAVES) + ni * 16 + lane % 16
                        if fx.const_expr(PF):
                            wi = ni * 4
                            wg, wu = fx.Vector(current_w[wi]), fx.Vector(current_w[wi + 1])
                            sg, su = fx.Int32(current_w[wi + 2]), fx.Int32(current_w[wi + 3])
                        else:
                            wg = _load4(W, _weight_offset(e, n, kg, 2 * I, D, ADDR_BITS), CACHE)
                            wu = _load4(W, _weight_offset(e, n + I, kg, 2 * I, D, ADDR_BITS), CACHE)
                            sg = _w2_scale(WS, e, n, kg, 2 * I, D, ADDR_BITS, PACKED)
                            su = _w2_scale(WS, e, n + I, kg, 2 * I, D, ADDR_BITS, PACKED)
                        for mi in fx.range_constexpr(BM // 16):
                            ai = (mi * (NR) + ni) * 2
                            accum[ai] = _mfma(av[mi], wg, accum[ai], asc[mi], sg)
                            accum[ai + 1] = _mfma(av[mi], wu, accum[ai + 1], asc[mi], su)
                if fx.const_expr(PF):
                    current_w = next_w
            if fx.const_expr(PF):
                accum = accum + current_w
            result = yield accum
        if fx.const_expr(FUSED_Q and BN // WAVES == 16 and QMAX):
            # Keep the BF16-rounded values in registers. Adjacent waves need
            # only each other's half-group maximum to form the MXFP4 scale.
            values, maxima = [], []
            for mi in fx.range_constexpr(BM // 16):
                gate, up = fx.Vector(result[mi * 2]), fx.Vector(result[mi * 2 + 1])
                for j in fx.range_constexpr(4):
                    local_row = mi * 16 + lane // 16 * 4 + j
                    x = _silu_bf16(gate[j], up[j])
                    a = fx.absf(x)
                    a = _epilogue_reduce(a, EPILOGUE_DPP)
                    values.append(x)
                    maxima.append(a)
                    if lane % 16 == 0:
                        fx.ptr_store(a, fx.add_offset(qshared, local_row * WAVES + wave))
            gpu.barrier()
            for mi in fx.range_constexpr(BM // 16):
                for j in fx.range_constexpr(4):
                    local_row = mi * 16 + lane // 16 * 4 + j
                    row = rb + local_row
                    other = fx.Float32(fx.ptr_load(fx.add_offset(qshared, local_row * WAVES + (wave ^ 1))))
                    a = _max(_max(maxima[mi * 4 + j], other), fx.Float32(1.0e-10))
                    bits = a.bitcast(fx.Int32)
                    exponent = ((bits >> 23) & 255) - 2 + ((bits & 0x7fffff) > 0x400000).select(fx.Int32(1), fx.Int32(0))
                    scale = (exponent << 23).bitcast(fx.Float32)
                    x = values[mi * 4 + j]
                    y = fx.Float32(gpu.shuffle_xor(x, 1, 64))
                    q = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x, y, scale, 0))
                    kg = (nbase + wave * 16) // 32
                    dst = fx.Int32(0)
                    if fx.const_expr(SORTED):
                        dst = (tile * (I // 32) + kg) * (BM + ROW_PAD) + local_row
                    else:
                        if row < count:
                            rid = _routed_row(Routes, e * R + row, tile, DIRECT)
                            dst = rid * (I // 32) + kg
                    if fx.const_expr(SORTED) or row < count:
                        if lane % 2 == 0:
                            _store(Q, dst * 16 + wave % 2 * 8 + lane % 16 // 2, q, fx.Uint8)
                        if lane % 16 == 0 and wave % 2 == 0:
                            _store(QS, dst, exponent, fx.Uint8)
        elif fx.const_expr(FUSED_Q and BN // WAVES == 16):
            # Each wave owns half of a 32-value MX group.
            # Exchange the BF16-rounded epilogue through padded LDS, then
            # quantize complete groups using 16 lanes per 32 values.
            for mi in fx.range_constexpr(BM // 16):
                gate, up = fx.Vector(result[mi * 2]), fx.Vector(result[mi * 2 + 1])
                for j in fx.range_constexpr(4):
                    local_row = mi * 16 + lane // 16 * 4 + j
                    col = wave * 16 + lane % 16
                    x = _silu_bf16(gate[j], up[j])
                    fx.ptr_store(x, fx.add_offset(qshared, local_row * (BN + 4) + col))
            gpu.barrier()
            for cp in fx.range_constexpr(BM * BN // (2 * THREADS)):
                t = tid + cp * THREADS
                local_row, col = t // (BN // 2), t % (BN // 2) * 2
                row = rb + local_row
                x0 = fx.Float32(fx.ptr_load(fx.add_offset(qshared, local_row * (BN + 4) + col)))
                x1 = fx.Float32(fx.ptr_load(fx.add_offset(qshared, local_row * (BN + 4) + col + 1)))
                a = _max(fx.absf(x0), fx.absf(x1))
                a = _epilogue_reduce(a, EPILOGUE_DPP)
                a = _max(a, fx.Float32(1.0e-10))
                bits = a.bitcast(fx.Int32)
                exponent = ((bits >> 23) & 255) - 2 + ((bits & 0x7fffff) > 0x400000).select(fx.Int32(1), fx.Int32(0))
                scale = (exponent << 23).bitcast(fx.Float32)
                q = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, x1, scale, 0))
                kg = (nbase + col) // 32
                dst = fx.Int32(0)
                if fx.const_expr(SORTED):
                    dst = (tile * (I // 32) + kg) * (BM + ROW_PAD) + local_row
                else:
                    if row < count:
                        rid = _routed_row(Routes, e * R + row, tile, DIRECT)
                        dst = rid * (I // 32) + kg
                if fx.const_expr(SORTED) or row < count:
                    _store(Q, dst * 16 + col % 32 // 2, q, fx.Uint8)
                    if col % 32 == 0:
                        _store(QS, dst, exponent, fx.Uint8)
        elif fx.const_expr(FUSED_Q):
            # Two adjacent 16-column fragments share one MXFP4 scale. Each
            # 16-lane subgroup owns all 32 values of one output row.
            for mi in fx.range_constexpr(BM // 16):
                for ni in fx.range_constexpr(BN // (WAVES * 32)):
                    ai = (mi * (NR) + ni * 2) * 2
                    gate0, up0 = fx.Vector(result[ai]), fx.Vector(result[ai + 1])
                    gate1, up1 = fx.Vector(result[ai + 2]), fx.Vector(result[ai + 3])
                    kg = (nbase + wave * (BN // WAVES)) // 32 + ni
                    for j in fx.range_constexpr(4):
                        local_row = mi * 16 + lane // 16 * 4 + j
                        row = rb + local_row
                        x0 = _silu_bf16(gate0[j], up0[j])
                        x1 = _silu_bf16(gate1[j], up1[j])
                        a = _max(fx.absf(x0), fx.absf(x1))
                        a = _epilogue_reduce(a, EPILOGUE_DPP)
                        a = _max(a, fx.Float32(1.0e-10))
                        bits = a.bitcast(fx.Int32)
                        exponent = ((bits >> 23) & 255) - 2 + ((bits & 0x7fffff) > 0x400000).select(fx.Int32(1), fx.Int32(0))
                        scale = (exponent << 23).bitcast(fx.Float32)
                        y0 = fx.Float32(gpu.shuffle_xor(x0, 1, 64))
                        y1 = fx.Float32(gpu.shuffle_xor(x1, 1, 64))
                        q0 = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, y0, scale, 0))
                        q1 = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x1, y1, scale, 0))
                        dst = fx.Int32(0)
                        if fx.const_expr(SORTED):
                            dst = (tile * (I // 32) + kg) * (BM + ROW_PAD) + local_row
                        else:
                            if row < count:
                                rid = _routed_row(Routes, e * R + row, tile, DIRECT)
                                dst = rid * (I // 32) + kg
                        if fx.const_expr(SORTED) or row < count:
                            if lane % 2 == 0:
                                if fx.const_expr(QSHUFFLE):
                                    local_kg = wave * (BN // WAVES // 32) + ni
                                    qoff = (local_kg * BM + local_row) * 16 + lane % 16 // 2
                                    fx.ptr_store(fx.Uint8(q0), fx.add_offset(qbytes, qoff))
                                    fx.ptr_store(fx.Uint8(q1), fx.add_offset(qbytes, qoff + 8))
                                else:
                                    _store(Q, dst * 16 + lane % 16 // 2, q0, fx.Uint8)
                                    _store(Q, dst * 16 + lane % 16 // 2 + 8, q1, fx.Uint8)
                            if lane % 16 == 0:
                                _store(QS, dst, exponent, fx.Uint8)
            if fx.const_expr(QSHUFFLE):
                # One lane writes one complete packed scale group, in the
                # tile-major layout read by the second projection.
                gpu.barrier()
                for cp in fx.range_constexpr((BM * (BN // 32) + THREADS - 1) // THREADS):
                    qi = tid + cp * THREADS
                    if qi < BM * (BN // 32):
                        local_kg, local_row = qi // BM, qi % BM
                        dst = (tile * (I // 32) + nbase // 32 + local_kg) * (BM + ROW_PAD) + local_row
                        qv = fx.ptr_load(fx.add_offset(qwords, qi * 4), result_type=T.i32x4)
                        fx.ptr_store(qv, fx.add_offset(_ptr(Q, fx.Int32, 16), dst * 4))
        else:
            for mi in fx.range_constexpr(BM // 16):
                for ni in fx.range_constexpr(NR):
                    ai = (mi * (NR) + ni) * 2
                    gate = fx.Vector(result[ai])
                    up = fx.Vector(result[ai + 1])
                    n = nbase + wave * (BN // WAVES) + ni * 16 + lane % 16
                    for j in fx.range_constexpr(4):
                        row = rb + mi * 16 + lane // 16 * 4 + j
                        if row < count:
                            rid = _routed_row(Routes, e * R + row, tile, DIRECT)
                            if fx.const_expr(PARTS > 1):
                                _store(H, (split * 2) * R * I + rid * I + n, gate[j], fx.Float32)
                                _store(H, (split * 2 + 1) * R * I + rid * I + n, up[j], fx.Float32)
                            else:
                                g = gate[j]
                                exp_neg = fx.Float32(rocdl.exp2(T.f32, fx.Float32(-g * fx.Float32(1.4426950408889634)).ir_value()))
                                inv = fx.Float32(rocdl.rcp(T.f32, fx.Float32(fx.Float32(1.0) + exp_neg).ir_value()))
                                val = (g * inv) * up[j]
                                _store(H, rid * I + n, val, fx.BFloat16)


@flyc.kernel
def _gemm1_split_fused(X: fx.Int64, A: fx.Int64, AS: fx.Int64, W: fx.Int64, WS: fx.Int64,
                       Ids: fx.Int64, Q: fx.Int64, QS: fx.Int64,
                       R: fx.Constexpr[int], D: fx.Constexpr[int], I: fx.Constexpr[int],
                       TOPK: fx.Constexpr[int], BN: fx.Constexpr[int], ADDR_BITS: fx.Constexpr[bool],
                       CACHE: fx.Constexpr[int], PACKED: fx.Constexpr[bool], LOCAL_A: fx.Constexpr[bool], LOCAL_VEC: fx.Constexpr[bool]):
    # The existing two K partitions run in separate sets of output waves.
    # One CTA owns both partial sums and the complete quantization groups.
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    split, nwave = wave // (BN // 16), wave % (BN // 16)
    ordered = _chiplet_order(fx.Int32(fx.block_idx.x), R * (I // BN))
    rid, nbase = ordered // (I // BN), ordered % (I // BN) * BN
    e = _load(Ids, rid)
    token = rid // TOPK
    n = nbase + nwave * 16 + lane % 16
    smem = fx.SharedAllocator()
    shared = fx.recast_iter(fx.Float32, smem.allocate(BN * 16, alignment=16).peek().ptr)
    if fx.const_expr(LOCAL_A):
        abytes = fx.recast_iter(fx.Uint8, smem.allocate(D // 2 + D // 32, alignment=16).peek().ptr)
        awords = fx.recast_iter(fx.Int32, abytes)
        if fx.const_expr(LOCAL_VEC):
            # Four adjacent lanes quantize a complete 32-value scale group.
            # Store eight packed values per word into the same LDS layout.
            for cp in fx.range_constexpr((D // 8 + BN * 8 - 1) // (BN * 8)):
                t = tid + cp * (BN * 8)
                if t < D // 8:
                    packed, exponent = _quantize_eight(X, token * (D // 8) + t)
                    fx.ptr_store(packed, fx.add_offset(awords, t))
                    if t % 4 == 0:
                        fx.ptr_store(fx.Uint8(exponent), fx.add_offset(abytes, D // 2 + t // 4))
        else:
            for cp in fx.range_constexpr((D // 2 + BN * 8 - 1) // (BN * 8)):
                t = tid + cp * (BN * 8)
                if t < D // 2:
                    x0 = fx.Float32(_load(X, token * D + t * 2, fx.BFloat16))
                    x1 = fx.Float32(_load(X, token * D + t * 2 + 1, fx.BFloat16))
                    a = _max(fx.absf(x0), fx.absf(x1))
                    for step in fx.range_constexpr(4):
                        a = _max(a, fx.Float32(gpu.shuffle_xor(a, 1 << step, 64)))
                    a = _max(a, fx.Float32(1.0e-10))
                    bits = a.bitcast(fx.Int32)
                    exponent = ((bits >> 23) & 255) - 2 + ((bits & 0x7fffff) > 0x400000).select(fx.Int32(1), fx.Int32(0))
                    scale = (exponent << 23).bitcast(fx.Float32)
                    packed = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, x1, scale, 0))
                    fx.ptr_store(fx.Uint8(packed), fx.add_offset(abytes, t))
                    if t % 16 == 0:
                        fx.ptr_store(fx.Uint8(exponent), fx.add_offset(abytes, D // 2 + t // 16))
        gpu.barrier()
    zeros = [fx.Vector.filled(4, 0.0, fx.Float32) for _ in range(2)]
    for kk, state in range(0, D // 256, 1, init=zeros):
        kg = (fx.Int32(kk) + split * (D // 256)) * 4 + lane // 16
        if fx.const_expr(LOCAL_A):
            av = fx.ptr_load(fx.add_offset(awords, kg * 4), result_type=T.i32x4)
            asc = fx.Int32(fx.ptr_load(fx.add_offset(abytes, D // 2 + kg)))
        else:
            av = _load4(A, token * (D // 8) + kg * 4)
            asc = fx.Int32(_load(AS, token * (D // 32) + kg, fx.Uint8))
        wg = _load4(W, _weight_offset(e, n, kg, 2 * I, D, ADDR_BITS), CACHE)
        wu = _load4(W, _weight_offset(e, n + I, kg, 2 * I, D, ADDR_BITS), CACHE)
        sg = _w2_scale(WS, e, n, kg, 2 * I, D, ADDR_BITS, PACKED)
        su = _w2_scale(WS, e, n + I, kg, 2 * I, D, ADDR_BITS, PACKED)
        gate = _mfma(av, wg, fx.Vector(state[0]), asc, sg)
        up = _mfma(av, wu, fx.Vector(state[1]), asc, su)
        result = yield [gate, up]
    if lane < 16:
        gate, up = fx.Vector(result[0]), fx.Vector(result[1])
        local_col = nwave * 16 + lane
        fx.ptr_store(gate[0], fx.add_offset(shared, split * (2 * BN) + local_col))
        fx.ptr_store(up[0], fx.add_offset(shared, split * (2 * BN) + BN + local_col))
    gpu.barrier()
    if tid < BN // 2:
        col = tid * 2
        g0 = fx.Float32(fx.ptr_load(fx.add_offset(shared, col))) + fx.Float32(fx.ptr_load(fx.add_offset(shared, 2 * BN + col)))
        g1 = fx.Float32(fx.ptr_load(fx.add_offset(shared, col + 1))) + fx.Float32(fx.ptr_load(fx.add_offset(shared, 2 * BN + col + 1)))
        u0 = fx.Float32(fx.ptr_load(fx.add_offset(shared, BN + col))) + fx.Float32(fx.ptr_load(fx.add_offset(shared, 3 * BN + col)))
        u1 = fx.Float32(fx.ptr_load(fx.add_offset(shared, BN + col + 1))) + fx.Float32(fx.ptr_load(fx.add_offset(shared, 3 * BN + col + 1)))
        x0, x1 = _silu_bf16(g0, u0), _silu_bf16(g1, u1)
        a = _max(fx.absf(x0), fx.absf(x1))
        for step in fx.range_constexpr(4):
            a = _max(a, fx.Float32(gpu.shuffle_xor(a, 1 << step, 64)))
        a = _max(a, fx.Float32(1.0e-10))
        bits = a.bitcast(fx.Int32)
        exponent = ((bits >> 23) & 255) - 2 + ((bits & 0x7fffff) > 0x400000).select(fx.Int32(1), fx.Int32(0))
        scale = (exponent << 23).bitcast(fx.Float32)
        packed = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, x1, scale, 0))
        _store(Q, rid * (I // 2) + nbase // 2 + tid, packed, fx.Uint8)
        if tid % 16 == 0:
            _store(QS, rid * (I // 32) + nbase // 32 + tid // 16, exponent, fx.Uint8)


@flyc.kernel
def _gemm1_grouped_split_fused(A: fx.Int64, AS: fx.Int64, W: fx.Int64, WS: fx.Int64,
                               Routes: fx.Int64, Counts: fx.Int64, TileE: fx.Int64,
                               TileR: fx.Int64, Total: fx.Int64, Q: fx.Int64, QS: fx.Int64,
                               R: fx.Constexpr[int], D: fx.Constexpr[int], I: fx.Constexpr[int],
                               TOPK: fx.Constexpr[int], BN: fx.Constexpr[int],
                               ADDR_BITS: fx.Constexpr[bool], CACHE: fx.Constexpr[int],
                               PACKED: fx.Constexpr[bool]):
    # Keep the expert's existing 16-row tile, with both K partitions in one
    # workgroup. Only live rows pass through the shared epilogue.
    BM = 16
    STRIDE = BN + 4
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    split, nwave = wave // (BN // 16), wave % (BN // 16)
    pid = fx.Int32(fx.block_idx.x)
    bound = _load(Total, 0) * (I // BN)
    shared = fx.recast_iter(fx.Float32, fx.SharedAllocator().allocate(4 * BM * STRIDE * 4, alignment=16).peek().ptr)
    if pid < bound:
        ordered = _chiplet_order(pid, bound)
        tile, nbase = ordered // (I // BN), ordered % (I // BN) * BN
        e = _load(TileE, tile)
        rb, count = _load(TileR, tile), _load(Counts, e)
        row = rb + lane % 16
        rid = fx.Int32(0)
        if row < count:
            rid = _load(Routes, e * R + row)
        token = rid // TOPK
        n = nbase + nwave * 16 + lane % 16
        zeros = [fx.Vector.filled(4, 0.0, fx.Float32) for _ in range(2)]
        for kk, state in range(0, D // 256, 1, init=zeros):
            kg = (fx.Int32(kk) + split * (D // 256)) * 4 + lane // 16
            av = _load4(A, token * (D // 8) + kg * 4)
            asc = fx.Int32(_load(AS, token * (D // 32) + kg, fx.Uint8))
            wg = _load4(W, _weight_offset(e, n, kg, 2 * I, D, ADDR_BITS), CACHE)
            wu = _load4(W, _weight_offset(e, n + I, kg, 2 * I, D, ADDR_BITS), CACHE)
            sg = _w2_scale(WS, e, n, kg, 2 * I, D, ADDR_BITS, PACKED)
            su = _w2_scale(WS, e, n + I, kg, 2 * I, D, ADDR_BITS, PACKED)
            gate = _mfma(av, wg, fx.Vector(state[0]), asc, sg)
            up = _mfma(av, wu, fx.Vector(state[1]), asc, su)
            result = yield [gate, up]
        gate, up = fx.Vector(result[0]), fx.Vector(result[1])
        for j in fx.range_constexpr(4):
            local_row = lane // 16 * 4 + j
            if rb + local_row < count:
                offset = (split * 2 * BM + local_row) * STRIDE + nwave * 16 + lane % 16
                fx.ptr_store(gate[j], fx.add_offset(shared, offset))
                fx.ptr_store(up[j], fx.add_offset(shared, offset + BM * STRIDE))
        gpu.barrier()
        for cp in fx.range_constexpr(BM // 16):
            t = tid + cp * (BN * 8)
            local_row, col = t // (BN // 2), t % (BN // 2) * 2
            if rb + local_row < count:
                offset = local_row * STRIDE + col
                g0 = fx.Float32(fx.ptr_load(fx.add_offset(shared, offset))) + fx.Float32(fx.ptr_load(fx.add_offset(shared, 2 * BM * STRIDE + offset)))
                g1 = fx.Float32(fx.ptr_load(fx.add_offset(shared, offset + 1))) + fx.Float32(fx.ptr_load(fx.add_offset(shared, 2 * BM * STRIDE + offset + 1)))
                u0 = fx.Float32(fx.ptr_load(fx.add_offset(shared, BM * STRIDE + offset))) + fx.Float32(fx.ptr_load(fx.add_offset(shared, 3 * BM * STRIDE + offset)))
                u1 = fx.Float32(fx.ptr_load(fx.add_offset(shared, BM * STRIDE + offset + 1))) + fx.Float32(fx.ptr_load(fx.add_offset(shared, 3 * BM * STRIDE + offset + 1)))
                x0, x1 = _silu_bf16(g0, u0), _silu_bf16(g1, u1)
                a = _max(fx.absf(x0), fx.absf(x1))
                for step in fx.range_constexpr(4):
                    a = _max(a, fx.Float32(gpu.shuffle_xor(a, 1 << step, 64)))
                a = _max(a, fx.Float32(1.0e-10))
                bits = a.bitcast(fx.Int32)
                exponent = ((bits >> 23) & 255) - 2 + ((bits & 0x7fffff) > 0x400000).select(fx.Int32(1), fx.Int32(0))
                scale = (exponent << 23).bitcast(fx.Float32)
                packed = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, x1, scale, 0))
                out_rid = _load(Routes, e * R + rb + local_row)
                _store(Q, out_rid * (I // 2) + nbase // 2 + col // 2, packed, fx.Uint8)
                if col % 32 == 0:
                    _store(QS, out_rid * (I // 32) + nbase // 32 + col // 32, exponent, fx.Uint8)


@flyc.kernel
def _activate_split(H: fx.Int64, Q: fx.Int64, S: fx.Int64,
                    TOTAL: fx.Constexpr[int], PARTS: fx.Constexpr[int]):
    t = fx.Int32(fx.block_idx.x) * 256 + fx.Int32(fx.thread_idx.x)
    if t < TOTAL // 2:
        g0, g1 = fx.Float32(0), fx.Float32(0)
        u0, u1 = fx.Float32(0), fx.Float32(0)
        for p in fx.range_constexpr(PARTS):
            g0 = g0 + _load(H, (p * 2) * TOTAL + t * 2, fx.Float32)
            g1 = g1 + _load(H, (p * 2) * TOTAL + t * 2 + 1, fx.Float32)
            u0 = u0 + _load(H, (p * 2 + 1) * TOTAL + t * 2, fx.Float32)
            u1 = u1 + _load(H, (p * 2 + 1) * TOTAL + t * 2 + 1, fx.Float32)
        e0 = fx.Float32(rocdl.exp2(T.f32, (-g0 * fx.Float32(1.4426950408889634)).ir_value()))
        e1 = fx.Float32(rocdl.exp2(T.f32, (-g1 * fx.Float32(1.4426950408889634)).ir_value()))
        r0 = fx.Float32(rocdl.rcp(T.f32, (fx.Float32(1) + e0).ir_value()))
        r1 = fx.Float32(rocdl.rcp(T.f32, (fx.Float32(1) + e1).ir_value()))
        x0 = fx.Float32(fx.BFloat16(g0 * r0 * u0))
        x1 = fx.Float32(fx.BFloat16(g1 * r1 * u1))
        a = _max(fx.absf(x0), fx.absf(x1))
        for step in fx.range_constexpr(4):
            a = _max(a, fx.Float32(gpu.shuffle_xor(a, 1 << step, 64)))
        a = _max(a, fx.Float32(1.0e-10))
        bits = a.bitcast(fx.Int32)
        exponent = ((bits >> 23) & 255) - 2 + ((bits & 0x7fffff) > 0x400000).select(fx.Int32(1), fx.Int32(0))
        scale = (exponent << 23).bitcast(fx.Float32)
        packed = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, x1, scale, 0))
        _store(Q, t, packed, fx.Uint8)
        if t % 16 == 0:
            _store(S, t // 16, exponent, fx.Uint8)


@flyc.kernel
def _gemm2(A: fx.Int64, AS: fx.Int64, W: fx.Int64, WS: fx.Int64,
           Routes: fx.Int64, Counts: fx.Int64, TileE: fx.Int64, TileR: fx.Int64,
           Total: fx.Int64, P: fx.Int64,
           R: fx.Constexpr[int], D: fx.Constexpr[int], I: fx.Constexpr[int],
           BM: fx.Constexpr[int], BN: fx.Constexpr[int], SORTED: fx.Constexpr[bool], LDS: fx.Constexpr[bool], PF: fx.Constexpr[bool], BF16_P: fx.Constexpr[bool], FP8_P: fx.Constexpr[bool], DIRECT: fx.Constexpr[bool], KSTEP: fx.Constexpr[int], WIDE: fx.Constexpr[bool], ADDR_BITS: fx.Constexpr[bool], GROUP_M: fx.Constexpr[int], CSHUFFLE: fx.Constexpr[bool], ROW_PAD: fx.Constexpr[int], CACHE: fx.Constexpr[int], PACKED: fx.Constexpr[bool], ROW_MAJOR: fx.Constexpr[bool]):
    FRAG = 32 if WIDE else 16
    ELEMENTS = 16 if WIDE else 4
    NR = BN // (FRAG * 4)
    KFACTOR = 2 if WIDE else 1
    EBYTES = 1 if FP8_P else (2 if BF16_P else 4)
    ESTRIDE = BN * EBYTES + 16
    ETYPE = fx.Uint8 if FP8_P else (fx.BFloat16 if BF16_P else fx.Float32)
    pid = fx.Int32(fx.block_idx.x)
    bound = fx.Int32(R * (D // BN))
    if fx.const_expr(not DIRECT):
        bound = _load(Total, 0) * (D // BN)
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    smem = fx.SharedAllocator()
    if fx.const_expr(LDS):
        shared = fx.recast_iter(fx.Int32, smem.allocate(BM * 4 * 20 * KSTEP, alignment=16).peek().ptr)
    if fx.const_expr(CSHUFFLE):
        eptr = smem.allocate(BM * ESTRIDE, alignment=16).peek().ptr
        evalues = fx.recast_iter(ETYPE, eptr)
        ewords = fx.recast_iter(fx.Int32, eptr)
    if pid < bound:
        ordered = _chiplet_order(pid, bound)
        tile = ordered // (D // BN)
        nbase = ordered % (D // BN) * BN
        e = _load(TileE, tile)
        rb, count = fx.Int32(0), fx.Int32(1)
        if fx.const_expr(not DIRECT):
            rb = _load(TileR, tile)
            count = _load(Counts, e)
        if fx.const_expr(GROUP_M > 1):
            member = (rb // BM) % GROUP_M
            first_row = rb - member * BM
            if first_row + (GROUP_M - 1) * BM < count:
                local = member * (D // BN) + ordered % (D // BN)
                tile = tile - member + local % GROUP_M
                rb = first_row + (local % GROUP_M) * BM
                nbase = (local // GROUP_M) * BN
        rows = []
        for mi in fx.range_constexpr(BM // FRAG):
            row = rb + mi * FRAG + lane % FRAG
            rid = fx.Int32(0)
            if row < count:
                rid = _routed_row(Routes, e * R + row, tile, DIRECT)
            rows.append(rid)
        zeros = [fx.Vector.filled(ELEMENTS, 0.0, fx.Float32) for _ in range(BM // FRAG * NR)]
        if fx.const_expr(PF):
            zeros = zeros + _w2_operands(W, WS, e, nbase, wave, lane, lane // FRAG, D, I, BN, FRAG, ADDR_BITS, CACHE, PACKED)
        for kk, state in range(0, I // 128, KSTEP, init=zeros):
            if fx.const_expr(SORTED and LDS):
                gpu.barrier()
                for cp in fx.range_constexpr((BM * 4 * KSTEP + 255) // 256):
                    ix = tid + cp * 256
                    if ix < BM * 4 * KSTEP:
                        gi = (tile * (I // 32) + fx.Int32(kk) * 4) * BM + ix
                        if fx.const_expr(ROW_PAD != 0):
                            gi = (tile * (I // 32) + fx.Int32(kk) * 4 + ix // BM) * (BM + ROW_PAD) + ix % BM
                        vv = _load4(A, gi * 4)
                        ss = fx.Int32(_load(AS, gi, fx.Uint8))
                        fx.ptr_store(vv, fx.add_offset(shared, ix * 4))
                        fx.ptr_store(ss, fx.add_offset(shared, BM * 16 * KSTEP + ix))
                gpu.barrier()
            accum = [fx.Vector(x) for x in state[:BM // FRAG * NR]]
            if fx.const_expr(PF):
                current_w = state[BM // FRAG * NR:]
            for ki in fx.range_constexpr(KSTEP * KFACTOR):
                kg = fx.Int32(kk) * 4 + ki * (4 // KFACTOR) + lane // FRAG
                if fx.const_expr(ROW_MAJOR):
                    # Retain the two weight fragments while streaming one
                    # activation row fragment at a time through the accumulators.
                    operands = _w2_operands(W, WS, e, nbase, wave, lane, kg, D, I, BN, FRAG, ADDR_BITS, CACHE, PACKED)
                    for mi in fx.range_constexpr(BM // FRAG):
                        ix = (ki * (4 // KFACTOR) + lane // FRAG) * BM + mi * FRAG + lane % FRAG
                        av = fx.ptr_load(fx.add_offset(shared, ix * 4), result_type=T.i32x4)
                        asc = fx.Int32(fx.ptr_load(fx.add_offset(shared, BM * 16 * KSTEP + ix)))
                        for ni in fx.range_constexpr(NR):
                            ai = mi * NR + ni
                            accum[ai] = _mfma2(av, fx.Vector(operands[ni * 2]), accum[ai], asc, fx.Int32(operands[ni * 2 + 1]), WIDE)
                else:
                    if fx.const_expr(SORTED):
                        if fx.const_expr(LDS):
                            indices = [(ki * (4 // KFACTOR) + lane // FRAG) * BM + mi * FRAG + lane % FRAG for mi in range(BM // FRAG)]
                            av = [fx.ptr_load(fx.add_offset(shared, indices[mi] * 4), result_type=T.i32x4) for mi in range(BM // FRAG)]
                            asc = [fx.Int32(fx.ptr_load(fx.add_offset(shared, BM * 16 * KSTEP + indices[mi]))) for mi in range(BM // FRAG)]
                        else:
                            indices = [(tile * (I // 32) + kg) * (BM + ROW_PAD) + mi * FRAG + lane % FRAG for mi in range(BM // FRAG)]
                            av = [_load4(A, indices[mi] * 4) for mi in range(BM // FRAG)]
                            asc = [fx.Int32(_load(AS, indices[mi], fx.Uint8)) for mi in range(BM // FRAG)]
                    else:
                        av = [_load4(A, rows[mi] * (I // 8) + kg * 4) for mi in range(BM // FRAG)]
                        asc = [fx.Int32(_load(AS, rows[mi] * (I // 32) + kg, fx.Uint8)) for mi in range(BM // FRAG)]
                    if fx.const_expr(PF):
                        nextkk = (fx.Int32(kk) * KFACTOR + ki + 1 < I // (128 // KFACTOR)).select(fx.Int32(kk) * KFACTOR + ki + 1, fx.Int32(kk) * KFACTOR + ki)
                        next_w = _w2_operands(W, WS, e, nbase, wave, lane, nextkk * (4 // KFACTOR) + lane // FRAG, D, I, BN, FRAG, ADDR_BITS, CACHE, PACKED)
                    for ni in fx.range_constexpr(NR):
                        n = nbase + wave * (BN // 4) + ni * FRAG + lane % FRAG
                        if fx.const_expr(PF):
                            wi = ni * 2
                            w, s = fx.Vector(current_w[wi]), fx.Int32(current_w[wi + 1])
                        else:
                            w = _load4(W, _weight_offset(e, n, kg, D, I, ADDR_BITS), CACHE)
                            s = _w2_scale(WS, e, n, kg, D, I, ADDR_BITS, PACKED)
                        for mi in fx.range_constexpr(BM // FRAG):
                            ai = mi * (NR) + ni
                            accum[ai] = _mfma2(av[mi], w, accum[ai], asc[mi], s, WIDE)
                if fx.const_expr(PF):
                    current_w = next_w
            if fx.const_expr(PF):
                accum = accum + current_w
            result = yield accum
        if fx.const_expr(BM // FRAG * NR == 1 and not PF):
            result = [result]
        for mi in fx.range_constexpr(BM // FRAG):
            for ni in fx.range_constexpr(NR):
                acc = fx.Vector(result[mi * (NR) + ni])
                n = nbase + wave * (BN // 4) + ni * FRAG + lane % FRAG
                for j in fx.range_constexpr(ELEMENTS):
                    row = rb + mi * FRAG + lane // FRAG * 4 + j
                    if fx.const_expr(WIDE):
                        # A 32x32 fragment returns four groups of four rows.
                        row = rb + mi * FRAG + lane // FRAG * 4 + (j // 4) * 8 + j % 4
                    if fx.const_expr(CSHUFFLE):
                        ecol = wave * (BN // 4) + ni * FRAG + lane % FRAG
                        if fx.const_expr(FP8_P):
                            epacked = fx.Int32(rocdl.cvt_pk_fp8_f32(T.i32, acc[j], acc[j], fx.Int32(0), False))
                            fx.ptr_store(fx.Uint8(epacked), fx.add_offset(evalues, (row - rb) * (ESTRIDE // EBYTES) + ecol))
                        else:
                            fx.ptr_store(ETYPE(acc[j]), fx.add_offset(evalues, (row - rb) * (ESTRIDE // EBYTES) + ecol))
                    elif row < count:
                        rid = _routed_row(Routes, e * R + row, tile, DIRECT)
                        if fx.const_expr(FP8_P):
                            packed = fx.Int32(rocdl.cvt_pk_fp8_f32(T.i32, acc[j], acc[j], fx.Int32(0), False))
                            _store(P, rid * D + n, packed, fx.Uint8)
                        elif fx.const_expr(BF16_P):
                            _store(P, rid * D + n, acc[j], fx.BFloat16)
                        else:
                            _store(P, rid * D + n, acc[j], fx.Float32)
        if fx.const_expr(CSHUFFLE):
            gpu.barrier()
            for cp in fx.range_constexpr((BM * BN * EBYTES + 4095) // 4096):
                pos = (tid + cp * 256) * 16
                local_row, local_col = pos // (BN * EBYTES), pos % (BN * EBYTES)
                if local_row < BM and rb + local_row < count:
                    rid = _routed_row(Routes, e * R + rb + local_row, tile, DIRECT)
                    v = fx.ptr_load(fx.add_offset(ewords, (local_row * ESTRIDE + local_col) // 4), result_type=T.i32x4)
                    fx.ptr_store(v, fx.add_offset(_ptr(P, fx.Int32, 16), ((rid * D + nbase) * EBYTES + local_col) // 4))


@flyc.kernel
def _gemm2_route_reduce(A: fx.Int64, AS: fx.Int64, W: fx.Int64, WS: fx.Int64,
                        Ids: fx.Int64, Weights: fx.Int64, Out: fx.Int64,
                        D: fx.Constexpr[int], I: fx.Constexpr[int],
                        TOPK: fx.Constexpr[int], BN: fx.Constexpr[int],
                        ADDR_BITS: fx.Constexpr[bool], CACHE: fx.Constexpr[int],
                        PACKED: fx.Constexpr[bool]):
    # One wave per route retains route parallelism while the workgroup owns
    # the complete token/output tile. Only the useful MFMA row is exchanged.
    tid = fx.Int32(fx.thread_idx.x)
    lane, route = tid % 64, tid // 64
    token = fx.Int32(fx.block_idx.y)
    nbase = _chiplet_order(fx.Int32(fx.block_idx.x), D // BN) * BN
    rid = token * TOPK + route
    e = _load(Ids, rid)
    shared = fx.recast_iter(fx.Float32, fx.SharedAllocator().allocate(TOPK * BN * 4, alignment=16).peek().ptr)
    zeros = [fx.Vector.filled(4, 0.0, fx.Float32) for _ in range(BN // 16)]
    for kk, state in range(0, I // 128, 1, init=zeros):
        kg = fx.Int32(kk) * 4 + lane // 16
        av = _load4(A, rid * (I // 8) + kg * 4)
        asc = fx.Int32(_load(AS, rid * (I // 32) + kg, fx.Uint8))
        accum = []
        for ni in fx.range_constexpr(BN // 16):
            n = nbase + ni * 16 + lane % 16
            w = _load4(W, _weight_offset(e, n, kg, D, I, ADDR_BITS), CACHE)
            s = _w2_scale(WS, e, n, kg, D, I, ADDR_BITS, PACKED)
            accum.append(_mfma(av, w, fx.Vector(state[ni]), asc, s))
        result = yield accum
    if fx.const_expr(BN == 16):
        result = [result]
    if lane < 16:
        for ni in fx.range_constexpr(BN // 16):
            acc = fx.Vector(result[ni])
            fx.ptr_store(acc[0], fx.add_offset(shared, route * BN + ni * 16 + lane))
    gpu.barrier()
    if tid < BN:
        value = fx.Float32(0)
        for k in fx.range_constexpr(TOPK):
            projected = fx.Float32(fx.ptr_load(fx.add_offset(shared, k * BN + tid)))
            weight = _load(Weights, token * TOPK + k, fx.Float32)
            value = value + weight * projected
        _store(Out, token * D + nbase + tid, value, fx.BFloat16)


@flyc.kernel
def _reduce(P: fx.Int64, Weights: fx.Int64, Out: fx.Int64,
            M: fx.Constexpr[int], D: fx.Constexpr[int], TOPK: fx.Constexpr[int], BF16_P: fx.Constexpr[bool], FP8_P: fx.Constexpr[bool]):
    x = fx.Int32(fx.block_idx.x) * 256 + fx.Int32(fx.thread_idx.x)
    if x < M * D:
        token, n = x // D, x % D
        value = fx.Float32(0)
        for k in fx.range_constexpr(TOPK):
            weight = _load(Weights, token * TOPK + k, fx.Float32)
            if fx.const_expr(FP8_P):
                packed = fx.Int32(_load(P, (token * TOPK + k) * D + n, fx.Uint8))
                projected = fx.Float32(rocdl.cvt_f32_fp8(T.f32, packed.ir_value(), 0))
            elif fx.const_expr(BF16_P):
                projected = fx.Float32(_load(P, (token * TOPK + k) * D + n, fx.BFloat16))
            else:
                projected = _load(P, (token * TOPK + k) * D + n, fx.Float32)
            value = value + weight * projected
        _store(Out, x, value, fx.BFloat16)


@flyc.kernel
def _reduce_fp8x4(P: fx.Int64, Weights: fx.Int64, Out: fx.Int64,
                  M: fx.Constexpr[int], D: fx.Constexpr[int], TOPK: fx.Constexpr[int]):
    x = fx.Int32(fx.block_idx.x) * 256 + fx.Int32(fx.thread_idx.x)
    if x < M * (D // 4):
        token, n = x // (D // 4), x % (D // 4)
        values = [fx.Float32(0) for _ in range(4)]
        for k in fx.range_constexpr(TOPK):
            weight = _load(Weights, token * TOPK + k, fx.Float32)
            packed = _load(P, (token * TOPK + k) * (D // 4) + n)
            for j in fx.range_constexpr(4):
                projected = fx.Float32(rocdl.cvt_f32_fp8(T.f32, packed.ir_value(), j))
                values[j] = values[j] + weight * projected
        output = fx.Vector.from_elements([fx.BFloat16(v) for v in values])
        fx.ptr_store(output, fx.add_offset(_ptr(Out, fx.BFloat16, 8), x * 4))


def build_mxfp4_moe_e33_i1024_module(num_tokens, model_dim, inter_dim, num_experts, topk):
    M, D, I, E, K = num_tokens, model_dim, inter_dim, num_experts, topk
    R = M * K
    # Reuse the direct fused projections for sparse multi-token batches.
    FUSED_TINY = _sweep_bool('FUSED_TINY', False) if 2 <= M <= 4 else False
    # Simpler addresses alter LLVM's unrolling and register allocation.
    ADDR_BITS = _sweep_bool('ADDR_BITS', M in (16, 64, 1024, 2048))
    # Simplify second-projection offsets without changing first-projection unrolling.
    ADDR_BITS2 = _sweep_bool('ADDR_BITS2', True)
    # Stream first-projection weights while expert row reuse is limited.
    # Larger batches retain the default policy for repeated weight panels.
    # The 48-row tile at 128 tokens also limits repeated weight-panel loads.
    cache128 = _sweep('CACHE1128', 2) if M == 128 else 0
    # Stream weights at 256 tokens, where 96-row tiles reduce panel reuse.
    cache256 = _sweep('CACHE1256', 2) if M == 256 else cache128
    CACHE1 = _sweep('CACHE1', 2 if 2 <= M <= 64 else cache256)
    CACHE2 = _sweep('CACHE2', 0)
    # Reuse aligned scale words across first-projection column and K fragments.
    PACKED_SCALES1 = _sweep_bool('PACKED_SCALES1', True)
    PACKED_SCALES2 = _sweep_bool('PACKED_SCALES2', True)
    GROUP_M = _sweep('GROUP_M', 4 if M >= 1024 else (2 if M == 512 else 1))
    # Group three row tiles to reuse each expert's weight panels.
    if M in (1024, 2048):
        GROUP_M = _sweep('GROUP_M_LARGE', 3)
    if M == 4096:
        # Keep groups of nine expert row tiles close in the launch order.
        GROUP_M = _sweep('GROUP_M4096', 9)
    sorted32 = _sweep_bool('SORTED32', False) if M == 32 else False
    bm32 = _sweep('BM32', 32 if sorted32 else 16) if M == 32 else 16
    bm64 = _sweep('BM64', 32) if M == 64 else 32
    # Keep the 64-column tile while reducing padded matrix rows.
    bm128 = _sweep('BM128', 48) if M == 128 else 32
    # A 96-row tile avoids reloading expert panels for short second tiles.
    bm256 = _sweep('BM256', 96) if M == 256 else 64
    bm4096 = _sweep('BM4096', 128) if M == 4096 else 128
    BM = _sweep('BM', bm32 if M == 32 else (bm64 if M == 64 else (bm128 if M == 128 else (bm256 if M == 256 else (16 if M < 32 else (32 if M <= 128 else (bm4096 if M >= 4096 else 64)))))))
    # Balance row reuse and accumulator registers with a 96-row tile.
    if M in (1024, 2048):
        BM = _sweep('BM_LARGE', 96)
    if M == 512:
        # Reuse each weight panel across 96 routed rows.
        BM = _sweep('BM512', 96)
    if M == 1024:
        BM = _sweep('BM1024', BM)
    if M == 2048:
        BM = _sweep('BM2048', BM)
    # Use wider output tiles from eight tokens.
    BN = _sweep('BN', _sweep('BN4', 64) if M == 4 else (64 if M < 8 else 128))
    # More waves share a wider output tile without growing per-wave accumulators.
    bn1_large = _sweep('BN14096', 128) if M == 4096 else BN
    bn1_base = _sweep('BN14', BN) if M == 4 else bn1_large
    bn1_small = _sweep('BN1_SMALL', bn1_base) if M <= 8 else bn1_base
    if 128 <= M <= 2048:
        # At 128 tokens, halve each wave's accumulator tile and double the grid.
        bn1_small = _sweep('BN1_MID', 64 if M == 128 else bn1_small)
    BN1 = _sweep('BN1', bn1_small)
    BN2 = _sweep('BN2', _sweep('BN24', BN) if M == 4 else BN)
    gather_small = _sweep_bool('GATHER_SMALL', True) if 64 <= M <= 128 else True
    SORTED = _sweep_bool('SORTED', (M >= 64 and gather_small) or sorted32)
    GATHER_TRANSPOSE = (_sweep_bool('GATHER_TRANSPOSE', M >= 256)
                        and SORTED and BM % 32 == 0 and D % 256 == 0)
    ROW_PAD = _sweep('ROW_PAD', 0) if SORTED else 0
    # Direct tiles can skip expert compaction for sparse route batches.
    direct4 = _sweep_bool('DIRECT4', False) if M == 4 else False
    DIRECT = _sweep_bool('DIRECT', M == 1 or direct4 or FUSED_TINY) and not SORTED
    # Two K partitions improve first-projection occupancy for tiny batches.
    PARTS = _sweep('SPLIT', _sweep('SPLIT1', 2) if M == 1 else (_sweep('SPLIT4', 2 if FUSED_TINY else 1) if M == 4 else (2 if M <= 2 else 1))) if M <= 32 else 1
    LDS = _sweep_bool('LDS', True) and SORTED
    PINGPONG1 = _sweep_bool('PINGPONG1', False) and LDS
    DMA1 = _sweep_bool('DMA1', False) and LDS
    pf128 = _sweep_bool('PF128', True) if M == 128 else False
    PF = _sweep_bool('PF', (pf128 if M == 128 else 64 <= M < 128) or sorted32)
    pf1_large = _sweep_bool('PF14096', True) if M == 4096 else PF
    if 128 <= M <= 2048:
        pf1_large = _sweep_bool('PF1_MID', pf1_large)
    pf1_small = _sweep_bool('PF1_SMALL', False) if M <= 8 else pf1_large
    PF1 = _sweep_bool('PF1', pf1_small)
    # Stage adjacent K slices together to amortize workgroup barriers.
    kstep128 = _sweep('KSTEP128', 2) if M == 128 else 1
    kstep2048 = _sweep('KSTEP2048', 2) if M == 2048 else kstep128
    KSTEP = _sweep('KSTEP', 2 if M in (64, 256, 512, 1024, 4096) else kstep2048)
    # Pair K slices for the 32-token first projection.
    KSTEP1 = _sweep('KSTEP1_DIRECT', 2 if M == 32 else 1) if not LDS else KSTEP
    KSTEP1 = _sweep('KSTEP1', KSTEP1)
    KSTEP2 = KSTEP if LDS else 1
    mfma32_large = _sweep_bool('MFMA32_LARGE', False) if M >= 1024 else False
    MFMA32 = _sweep_bool('MFMA32', M in (64, 256, 512) or mfma32_large) and SORTED and BM % 32 == 0 and BN2 % 128 == 0
    FUSED_Q = _sweep_bool('FUSED_Q', True) and PARTS == 1
    QMAX = _sweep_bool('QMAX4', False) if M == 4 else (_sweep_bool('QMAX4096', True) if M == 4096 else False)
    if M in (8, 16):
        QMAX = _sweep_bool('QMAX_SMALL', False)
    if 128 <= M <= 2048:
        # Paired waves share only group maxima for the 64-column tile at
        # 128 tokens, reducing quantization LDS to four floats per row.
        QMAX = _sweep_bool('QMAX_MID', M == 128 or QMAX)
    if M == 2048:
        QMAX = _sweep_bool('QMAX2048', QMAX)
    # Eight waves reduce per-wave accumulators at the selected small batches.
    waves1_small = _sweep('WAVES1_SMALL', 8 if M in (8, 16) else 4) if M <= 32 else (8 if M == 4096 and BN1 >= 128 else 4)
    if M == 4:
        waves1_small = _sweep('WAVES14', waves1_small)
    if 128 <= M <= 2048:
        waves1_small = _sweep('WAVES1_MID', waves1_small)
    WAVES1 = _sweep('WAVES1', waves1_small)
    if M == 2048:
        WAVES1 = _sweep('WAVES12048', WAVES1)
    if M == 4096:
        # Each wave owns a complete 32-column quantization group.
        WAVES1 = _sweep('WAVES14096', 4)
    # Native subgroup maxima shorten the epilogue at the measured shapes.
    EPILOGUE_DPP = _sweep_bool('EPILOGUE_DPP', M in (4, 64) or M >= 256)
    QSHUFFLE = (_sweep_bool('QSHUFFLE', M in (64, 256, 512, 1024, 2048, 4096))
                and SORTED and FUSED_Q and BN1 // WAVES1 >= 32)
    # Narrow the routed-result buffer from 128 tokens; accumulation stays FP32.
    BF16_P = _sweep_bool('BF16_P', M >= 128)
    # Reuse the packed FP8 stores and vectorized reduction from 16 tokens.
    # Both projection and routing-weight accumulation remain FP32.
    FP8_P = _sweep_bool('FP8_P', M in (16, 32, 64) or M >= 128)
    FUSED_ROUTE_REDUCE = (_sweep_bool('FUSED_ROUTE_REDUCE', M == 1 or FUSED_TINY)
                          if M <= 4 else False) and not SORTED and not FP8_P and not BF16_P
    REDUCE_BN = _sweep('REDUCE_BN', 16) if FUSED_ROUTE_REDUCE else 16
    FUSED_SPLIT1 = (_sweep_bool('FUSED_SPLIT1', M == 1 or FUSED_TINY) if M <= 4 else False) and DIRECT and PARTS == 2 and BN1 == 64
    SPLIT_FUSED_BN = _sweep('SPLIT_FUSED_BN', 128) if FUSED_SPLIT1 else 128
    # The single input row fits in LDS and its quantization replaces a launch.
    FUSED_INPUT1 = _sweep_bool('FUSED_INPUT1', M == 1 or FUSED_TINY) and FUSED_SPLIT1
    FUSED_INPUT_VEC = _sweep_bool('FUSED_INPUT_VEC', True) and FUSED_INPUT1 and D % 32 == 0
    FUSED_GROUP_SPLIT = (_sweep_bool('FUSED_GROUP_SPLIT', True) if M == 2 else False) and not SORTED and not DIRECT and PARTS == 2 and BM == 16 and BN1 == 64 and WAVES1 == 4
    GROUP_SPLIT_BN = _sweep('GROUP_SPLIT_BN', 64) if FUSED_GROUP_SPLIT else 64
    # Preserve scratch allocation capacity while reducing device memory traffic.
    FP8_RESERVE = _sweep_bool('FP8_RESERVE', True) if M <= 64 and FP8_P else False
    CSHUFFLE2 = _sweep_bool('CSHUFFLE2', True) and (FP8_P or _sweep_bool('CSHUFFLE_FP32', False))
    # Stream activation fragments through the retained weight fragments.
    ROW_MAJOR1 = _sweep_bool('ROW_MAJOR1', M >= 512) and LDS and not PF1
    ROW_MAJOR2 = _sweep_bool('ROW_MAJOR2', M >= 512) and LDS and not PF
    # Amortize contended expert-counter updates across all four waves.
    BLOCK_ROUTE = _sweep_bool('BLOCK_ROUTE', True) if M >= 256 else False
    EXPERT_ROUTE = _sweep_bool('EXPERT_ROUTE', M in (1024, 4096))
    fused_route_small = _sweep_bool('FUSED_ROUTE_SMALL', False) if 2 <= M <= 128 else False
    FUSED_ROUTE = _sweep_bool('FUSED_ROUTE', fused_route_small)
    ROUTE_WAVES = _sweep('ROUTE_WAVES', 16)
    # Tiny batches share one launch for input quantization and expert routing.
    quant_route_default = _sweep_bool('QUANT_ROUTE_MID', False) if 64 <= M <= 128 else True
    QUANT_ROUTE = _sweep_bool('QUANT_ROUTE', quant_route_default) and not DIRECT if 2 <= M <= 128 else False
    # Overlap quantization and the expert scans in a single preparation grid.
    QUANT_EXPERT_ROUTE = _sweep_bool('QUANT_EXPERT_ROUTE', M >= 64) and not DIRECT and not QUANT_ROUTE and not FUSED_ROUTE
    # Shorten both parallel preparation tasks for the larger routed batches.
    QUANT_VEC = _sweep_bool('QUANT_VEC', M >= 1024) and D % 32 == 0
    ROUTE_TWO_PASS = _sweep_bool('ROUTE_TWO_PASS', M >= 1024) and M >= 64
    # Gather workgroups derive their own mapping; one writer per tile saves
    # metadata for the following projections after this launch completes.
    FUSED_GATHER_TILES = _sweep_bool('FUSED_GATHER_TILES', 64 <= M <= 1024) and SORTED and not FUSED_ROUTE and not QUANT_ROUTE
    max_tiles = (R + BM - 1) // BM + E
    if _sweep_bool('TIGHT_TILES', False):
        # A nonempty expert takes one route for its first tile and BM more
        # routes for every additional tile. Maximize over at most E experts.
        max_tiles = min(R, E + (R - E) // BM)
    if DIRECT:
        max_tiles = R
    device = 'cuda'
    aq = torch.empty((M, D // 2), device=device, dtype=torch.uint8)
    asc = torch.empty((M, D // 32), device=device, dtype=torch.uint8)
    counts = torch.empty(E, device=device, dtype=torch.int32)
    routes = torch.empty((E, R), device=device, dtype=torch.int32)
    te = torch.empty(max_tiles, device=device, dtype=torch.int32)
    tr = torch.empty(max_tiles, device=device, dtype=torch.int32)
    total = torch.empty(1, device=device, dtype=torch.int32)
    h = torch.empty((R, I), device=device, dtype=torch.bfloat16)
    hp = torch.empty((PARTS, 2, R, I), device=device, dtype=torch.float32) if PARTS > 1 and not FUSED_GROUP_SPLIT else h
    hq = torch.empty((R, I // 2), device=device, dtype=torch.uint8)
    hs = torch.empty((R, I // 32), device=device, dtype=torch.uint8)
    p = torch.empty((R, D * (4 if FP8_RESERVE else 1)), device=device, dtype=torch.float8_e4m3fn if FP8_P else (torch.bfloat16 if BF16_P else torch.float32))
    aqg = torch.empty((max_tiles, BM + ROW_PAD, D // 2), device=device, dtype=torch.uint8) if SORTED else aq
    asg = torch.empty((max_tiles, BM + ROW_PAD, D // 32), device=device, dtype=torch.uint8) if SORTED else asc
    hqg = torch.empty((max_tiles, BM + ROW_PAD, I // 2), device=device, dtype=torch.uint8) if SORTED else hq
    hsg = torch.empty((max_tiles, BM + ROW_PAD, I // 32), device=device, dtype=torch.uint8) if SORTED else hs
    scratch = [aq, asc, counts, routes, te, tr, total, h, hq, hs, p, aqg, asg, hqg, hsg, hp]
    addresses = [x.data_ptr() for x in scratch]
    # Out is a launch argument between P and AQG.
    addr_a, addr_b = addresses[:11], addresses[11:]

    @flyc.jit
    def run(X: fx.Int64, W1: fx.Int64, W2: fx.Int64, Weights: fx.Int64,
            Ids: fx.Int64, S1: fx.Int64, S2: fx.Int64,
            AQ: fx.Int64, ASC: fx.Int64, Counts: fx.Int64, Routes: fx.Int64,
            TE: fx.Int64, TR: fx.Int64, Total: fx.Int64, H: fx.Int64,
            HQ: fx.Int64, HS: fx.Int64, P: fx.Int64, Out: fx.Int64,
            AQG: fx.Int64, ASG: fx.Int64, HQG: fx.Int64, HSG: fx.Int64, HP: fx.Int64,
            Enabled: fx.Int32, stream: fx.Stream):
        """Launch expert-local groups of row tiles sharing weight panels."""
        # flyc.compile also calls the compiled host wrapper once. Its dry call
        # has no input tensors yet; every real invocation sets Enabled to one.
        if Enabled != 0:
            if fx.const_expr(not QUANT_ROUTE and not QUANT_EXPERT_ROUTE and not FUSED_INPUT1):
                _quantize(X, AQ, ASC, Counts, M * D, E, not DIRECT).launch(grid=((M * D // 2 + 255) // 256,), block=(256,), stream=stream)
            if fx.const_expr(QUANT_EXPERT_ROUTE):
                _route_expert(Ids, Counts, Routes, R, ROUTE_WAVES, X, AQ, ASC, M * D, E, True, QUANT_VEC, ROUTE_TWO_PASS).launch(grid=(max(E, (M * D // (8 if QUANT_VEC else 2) + ROUTE_WAVES * 64 - 1) // (ROUTE_WAVES * 64)),), block=(ROUTE_WAVES * 64,), stream=stream)
            elif fx.const_expr(QUANT_ROUTE):
                _quantize_route_fused(X, AQ, ASC, Ids, Counts, Routes, TE, TR, Total, M * D, R, E, BM, ROUTE_WAVES).launch(grid=((M * D // 2 + ROUTE_WAVES * 64 - 1) // (ROUTE_WAVES * 64),), block=(ROUTE_WAVES * 64,), stream=stream)
            elif fx.const_expr(DIRECT):
                TE = Ids
            elif fx.const_expr(FUSED_ROUTE):
                _route_fused(Ids, Counts, Routes, TE, TR, Total, R, E, BM, ROUTE_WAVES).launch(grid=(1,), block=(ROUTE_WAVES * 64,), stream=stream)
            elif fx.const_expr(EXPERT_ROUTE):
                _route_expert(Ids, Counts, Routes, R, ROUTE_WAVES, X, AQ, ASC, M * D, E, False, False, ROUTE_TWO_PASS).launch(grid=(E,), block=(ROUTE_WAVES * 64,), stream=stream)
            elif fx.const_expr(BLOCK_ROUTE):
                _route_block(Ids, Counts, Routes, R).launch(grid=((R + 255) // 256, E), block=(256,), stream=stream)
            else:
                _route(Ids, Counts, Routes, R).launch(grid=((R + 255) // 256, E), block=(256,), stream=stream)
            if fx.const_expr(not DIRECT and not FUSED_ROUTE and not QUANT_ROUTE and not FUSED_GATHER_TILES):
                _route_tiles(Counts, TE, TR, Total, E, BM).launch(grid=(1,), block=(64,), stream=stream)
            if fx.const_expr(SORTED):
                if fx.const_expr(GATHER_TRANSPOSE):
                    _gather_quant_coalesced(AQ, ASC, AQG, ASG, Routes, Counts, TE, TR, Total, R, D, K, BM, ROW_PAD, E, FUSED_GATHER_TILES).launch(grid=((BM * (D // 32) + 255) // 256, max_tiles), block=(256,), stream=stream)
                else:
                    _gather_quant(AQ, ASC, AQG, ASG, Routes, Counts, TE, TR, Total, R, D, K, BM, ROW_PAD, E, FUSED_GATHER_TILES).launch(grid=((BM * (D // 32) + 255) // 256, max_tiles), block=(256,), stream=stream)
            if fx.const_expr(FUSED_SPLIT1):
                _gemm1_split_fused(X, AQ, ASC, W1, S1, Ids, HQ, HS, R, D, I, K, SPLIT_FUSED_BN, ADDR_BITS, CACHE1, PACKED_SCALES1, FUSED_INPUT1, FUSED_INPUT_VEC).launch(grid=(R * (I // SPLIT_FUSED_BN),), block=(SPLIT_FUSED_BN * 8,), stream=stream)
            elif fx.const_expr(FUSED_GROUP_SPLIT):
                _gemm1_grouped_split_fused(AQ, ASC, W1, S1, Routes, Counts, TE, TR, Total, HQ, HS, R, D, I, K, GROUP_SPLIT_BN, ADDR_BITS, CACHE1, PACKED_SCALES1).launch(grid=(max_tiles * (I // GROUP_SPLIT_BN),), block=(GROUP_SPLIT_BN * 8,), stream=stream)
            else:
                _gemm1(AQG, ASG, W1, S1, Routes, Counts, TE, TR, Total, HP, HQG, HSG, R, D, I, K, BM, BN1, SORTED, PARTS, LDS, PF1, FUSED_Q, QMAX, DIRECT, KSTEP1, WAVES1, ADDR_BITS, GROUP_M, PINGPONG1, DMA1, ROW_PAD, CACHE1, PACKED_SCALES1, ROW_MAJOR1, QSHUFFLE, EPILOGUE_DPP).launch(grid=(max_tiles * (I // BN1), PARTS), block=(WAVES1 * 64,), stream=stream)
            if fx.const_expr(FUSED_SPLIT1 or FUSED_GROUP_SPLIT):
                pass
            elif fx.const_expr(PARTS > 1):
                _activate_split(HP, HQ, HS, R * I, PARTS).launch(grid=((R * I // 2 + 255) // 256,), block=(256,), stream=stream)
            elif fx.const_expr(not FUSED_Q):
                _quantize(H, HQ, HS, Counts, R * I, E, False).launch(grid=((R * I // 2 + 255) // 256,), block=(256,), stream=stream)
            if fx.const_expr(SORTED and not FUSED_Q):
                _gather_quant(HQ, HS, HQG, HSG, Routes, Counts, TE, TR, Total, R, I, 1, BM, ROW_PAD, E, False).launch(grid=((BM * (I // 32) + 255) // 256, max_tiles), block=(256,), stream=stream)
            if fx.const_expr(FUSED_ROUTE_REDUCE):
                _gemm2_route_reduce(HQ, HS, W2, S2, Ids, Weights, Out, D, I, K, REDUCE_BN, ADDR_BITS2, CACHE2, PACKED_SCALES2).launch(grid=(D // REDUCE_BN, M), block=(K * 64,), stream=stream)
            else:
                _gemm2(HQG, HSG, W2, S2, Routes, Counts, TE, TR, Total, P, R, D, I, BM, BN2, SORTED, LDS, PF, BF16_P, FP8_P, DIRECT, KSTEP2, MFMA32, ADDR_BITS2, GROUP_M, CSHUFFLE2, ROW_PAD, CACHE2, PACKED_SCALES2, ROW_MAJOR2).launch(grid=(max_tiles * (D // BN2),), block=(256,), stream=stream)
            if fx.const_expr(FUSED_ROUTE_REDUCE):
                pass
            elif fx.const_expr(FP8_P):
                _reduce_fp8x4(P, Weights, Out, M, D, K).launch(grid=((M * D // 4 + 255) // 256,), block=(256,), stream=stream)
            else:
                _reduce(P, Weights, Out, M, D, K, BF16_P, FP8_P).launch(grid=((M * D + 255) // 256,), block=(256,), stream=stream)

    compiled = flyc.compile(run, *([0] * 7), *addr_a, 0, *addr_b, 0, fx.Stream(None))

    def launch(hidden_states, w1, w2, topk_weight, topk_ids, w1_scale, w2_scale, out):
        args = [x.data_ptr() for x in (hidden_states, w1, w2, topk_weight, topk_ids, w1_scale, w2_scale)]
        compiled(*args, *addr_a, out.data_ptr(), *addr_b, 1, fx.Stream(torch.cuda.current_stream()))

    launch.scratch = scratch
    return launch


# ---------------------------------------------------------------------------
# The workload schema's entry point. The factory compiles for one shape, so
# built launches are cached by shape: calling the factory per invocation would
# recompile every time. The first call for a new shape therefore includes
# compilation.
# ---------------------------------------------------------------------------

_RUN_CACHE: dict[tuple[int, int, int, int, int], object] = {}


def run(*, hidden_states, w1, w2, topk_weights, topk_ids, w1_scale, w2_scale, activation,
        quant_type, doweight_stage1, gate_mode, act_quant, expert_mask, beta, linear_beta,
        out_dtype, out):
    """Fused MoE over mxfp4 weights, written into ``out``.

    Attrs are ignored: dispatch only routes this schema's point (SiLU,
    stage-2 routing weights), which this specialization hard-codes.
    """
    num_tokens = int(hidden_states.shape[0])
    model_dim = int(hidden_states.shape[-1])
    num_experts = int(w1.shape[0])
    inter_dim = int(w1.shape[1]) // 2
    topk = int(topk_ids.shape[-1])
    key = (num_tokens, model_dim, inter_dim, num_experts, topk)
    launch = _RUN_CACHE.get(key)
    if launch is None:
        launch = build_mxfp4_moe_e33_i1024_module(
            num_tokens=num_tokens,
            model_dim=model_dim,
            inter_dim=inter_dim,
            num_experts=num_experts,
            topk=topk,
        )
        _RUN_CACHE[key] = launch
    launch(hidden_states, w1, w2, topk_weights, topk_ids, w1_scale, w2_scale, out)
